window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/musculo-squelettique","titre":"Conditions Musculo-squelettiques","sources":[{"t":"Concepts de base sur les lésions","q":"cours-01-concepts-de-base/quiz.html","f":"cours-01-concepts-de-base/fiche.html"},{"t":"Lésions musculaires","q":"cours-02-lesions-musculaires/quiz.html","f":"cours-02-lesions-musculaires/fiche.html"},{"t":"Lésions tendineuses","q":"cours-03-lesions-tendineuses/quiz.html","f":"cours-03-lesions-tendineuses/fiche.html"},{"t":"Lésions capsulo-ligamentaires","q":"cours-04-lesions-capsulo-ligamentaires/quiz.html","f":"cours-04-lesions-capsulo-ligamentaires/fiche.html"},{"t":"Dysfonctions biomécaniques","q":"cours-05-dysfonctions-biomecaniques/quiz.html","f":"cours-05-dysfonctions-biomecaniques/fiche.html"},{"t":"Dysfonctions du tissu osseux et cartilagineux","q":"cours-06-tissu-osseux-cartilagineux/quiz.html","f":"cours-06-tissu-osseux-cartilagineux/fiche.html"},{"t":"Dysfonctions vertébrales et radiculaires","q":"cours-07-dysfonctions-vertebrales/quiz.html","f":"cours-07-dysfonctions-vertebrales/fiche.html"},{"t":"Dysfonctions rhumatologiques et conditions métaboliques","q":"cours-08-rhumatologie-metabolique/quiz.html","f":"cours-08-rhumatologie-metabolique/fiche.html"},{"t":"Principes de l'exercice en CMS","q":"cours-09-exercice-en-cms/quiz.html","f":"cours-09-exercice-en-cms/fiche.html"}],"questions":[{"q":"Parmi ces structures, laquelle appartient aux tissus contractiles ?","o":["La structure musculo-tendineuse","Le ligament collatéral médial","La capsule articulaire","Le fascia superficiel du membre"],"r":0,"e":"Seules les structures musculo-tendineuses sont classées comme contractiles, même si le tendon ne se contracte pas de façon directe.","s":0},{"q":"Quelle est la fonction principale des tissus non contractiles ?","o":["Soutien, stabilité, transmission de force","Production du mouvement, contraction","Conduction nerveuse, transmission sensitive","Stockage d'énergie, chimique et thermique"],"r":0,"e":"Ligaments, capsules, fascias, cartilage et tissu conjonctif assurent soutien, stabilité et transmission de force.","s":0},{"q":"Quelle propriété mécanique du muscle correspond au retour à la longueur d'origine ?","o":["L'élasticité","L'extensibilité","La contractilité","La viscosité"],"r":0,"e":"Extensibilité = s'allonger ; élasticité = revenir à la longueur d'origine ; contractilité = générer une tension ; viscosité = résister à la déformation rapide.","s":0},{"q":"Quelle propriété correspond à la résistance à la déformation rapide ?","o":["La viscosité","L'élasticité","L'extensibilité","La contractilité"],"r":0,"e":"La viscosité est la résistance opposée à une déformation rapide.","s":0},{"q":"Quel est le pourcentage de collagène de type I dans le tendon ?","o":["85 à 95 %","40 à 50 %","20 à 30 %","100 %"],"r":0,"e":"Le tendon est riche en collagène de type I, à hauteur de 85 à 95 %.","s":0},{"q":"Que signifie « comportement viscoélastique » pour le tendon ?","o":["Une déformation qui dépend du temps et de la charge","Une déformation qui dépend seulement de la charge appliquée","Aucune déformation, quelle que soit la charge","Une rupture dès la première contrainte appliquée"],"r":0,"e":"Viscoélastique = la déformation dépend à la fois du temps d'application et de l'intensité de la charge.","s":0},{"q":"Quelle cellule est prédominante dans le tissu conjonctif proprement dit ?","o":["Le fibroblaste","L'ostéoclaste","Le chondrocyte","Le myofibroblaste"],"r":0,"e":"Le fibroblaste est la cellule prédominante : il synthétise le collagène et répond aux stimuli mécaniques.","s":0},{"q":"Comment appelle-t-on le fibroblaste mature d'aspect fusiforme ?","o":["Le fibrocyte","Le myofibroblaste","Le mastocyte","L'adipocyte"],"r":0,"e":"Le fibrocyte est le fibroblaste arrivé à maturation.","s":0},{"q":"De quoi est composée la matrice extracellulaire du tissu conjonctif proprement dit ?","o":["De fibres et de substance fondamentale amorphe","Uniquement de fibres de collagène de type I","Uniquement de cellules, sans aucune fibre","De calcium et de phosphate, comme l'os"],"r":0,"e":"Fibres (élastiques, de collagène, réticulaires) + substance fondamentale composée d'eau, protéines, glucides et lipides.","s":0},{"q":"Quelle affirmation sur les cross-links est correcte ?","o":["Plus de cross-links = plus de résistance, moins de mobilité","Plus de cross-links = plus de mobilité, moins de résistance","Les cross-links n'influencent ni la résistance ni la mobilité","Les cross-links diminuent la résistance du tissu à la tension"],"r":0,"e":"Le nombre de cross-links détermine la résistance de la structure, au prix de la mobilité.","s":0},{"q":"Que provoque l'immobilisation au niveau du tissu conjonctif ?","o":["Moins de substance amorphe et plus de cross-links","Plus de substance amorphe et moins de cross-links","Une destruction complète du collagène du tissu","Aucune modification de la structure du tissu"],"r":0,"e":"L'immobilisation diminue la substance amorphe (++ GAG), ce qui augmente le nombre de cross-links et fait perdre de la mobilité.","s":0},{"q":"Qu'est-ce que le creep (fluage) ?","o":["Une déformation progressive du tissu sous une force constante","Une baisse de la force nécessaire pour garder une déformation","Une rupture brutale du tissu sous une charge maximale","Un retour élastique immédiat du tissu après la charge"],"r":0,"e":"Le creep = capacité du tissu à se déformer dans le temps sous force constante jusqu'à un état d'équilibre.","s":0},{"q":"Qu'est-ce que la stress-relaxation ?","o":["Une baisse de la force nécessaire pour garder la déformation","Un allongement progressif du tissu sous une force constante","Une perte définitive de l'élasticité du tissu après la charge","Une augmentation de la contrainte au cours du temps"],"r":0,"e":"La relaxation se définit comme la diminution de la force nécessaire pour maintenir une déformation donnée dans le temps.","s":0},{"q":"À partir de quel pourcentage de déformation apparaissent les micro-lésions ?","o":["4 %","1 %","8 %","15 %"],"r":0,"e":"Sur la courbe contrainte/déformation : micro-lésions à partir de 4 %, macro-lésions à partir de 8 %.","s":0},{"q":"À partir de quel pourcentage de déformation apparaissent les macro-lésions ?","o":["8 %","4 %","2 %","20 %"],"r":0,"e":"Les macro-lésions surviennent à partir de 8 % de déformation.","s":0},{"q":"Une lésion produite par une surcharge répétitive est dite :","o":["Microtraumatique","Macrotraumatique","Congénitale","Dégénérative pure"],"r":0,"e":"La lésion microtraumatique résulte d'une surcharge répétitive ou d'un mécanisme incorrect d'utilisation.","s":0},{"q":"Quelle est la caractéristique clinique d'une lésion macrotraumatique ?","o":["Douleur et incapacité immédiates","Installation lente sur plusieurs mois","Absence totale de douleur","Symptômes uniquement nocturnes"],"r":0,"e":"Produit d'un traumatisme aigu, elle cause douleur et incapacité immédiates.","s":0},{"q":"Quels sont les objectifs généraux face à une lésion des tissus mous ?","o":["Contrôler l'inflammation, limiter les complications, favoriser la réparation","Supprimer toute l'inflammation dès la première heure qui suit la lésion","Immobiliser définitivement le segment, jusqu'à la cicatrisation complète","Renforcer immédiatement à charge maximale, pour éviter l'atrophie"],"r":0,"e":"Ce sont les trois objectifs généraux énoncés dans le cours.","s":0},{"q":"Dans quel ordre se succèdent les phases de cicatrisation ?","o":["Inflammatoire → réparation → remodelage","Réparation → inflammatoire → remodelage","Remodelage → inflammatoire → réparation","Inflammatoire → remodelage → réparation"],"r":0,"e":"La cascade est toujours : inflammation, puis réparation, puis remodelage.","s":0},{"q":"Quelle phase détermine la forme et la fonction finales du tissu ?","o":["La phase de remodelage","La phase inflammatoire","La phase de réparation","La phase de granulation"],"r":0,"e":"C'est le remodelage (régénération) qui détermine la forme et la fonction finales.","s":0},{"q":"Sur quoi la phase inflammatoire est-elle fondée ?","o":["Sur la vascularisation","Sur l'innervation","Sur la minéralisation","Sur la contraction musculaire"],"r":0,"e":"La réponse inflammatoire est une réponse biologique séquentielle fondée sur la vascularisation.","s":0},{"q":"Quelle liste ne contient que des substances algogènes endogènes ?","o":["Prostaglandines, substance P, sérotonine, bradykinine","Collagène, élastine, kératine, fibronectine, laminine","Ostéocalcine, vitamine D, calcium, phosphate","Actine, myosine, titine, tropomyosine"],"r":0,"e":"Ce sont les substances libérées par les cellules endommagées qui agissent sur les récepteurs de la douleur. L'histamine en fait aussi partie.","s":0},{"q":"Quels mécanismes expliquent l'œdème en phase inflammatoire ?","o":["La stase et la libération de fluides","La vasoconstriction et la déshydratation","La minéralisation de la matrice","La contraction des myofibroblastes"],"r":0,"e":"L'œdème résulte de la stase circulatoire et de la libération de fluides.","s":0},{"q":"Quel objectif appartient à la phase inflammatoire ?","o":["Entretenir la mobilité et la force des segments non atteints","Reprendre la compétition dès que la douleur le permet","Travailler à charge maximale sur la zone lésée","Normaliser complètement l'amplitude du segment lésé, dès les premiers jours"],"r":0,"e":"En phase inflammatoire on protège la zone lésée mais on entretient les segments voisins non atteints.","s":0},{"q":"Quelle est l'évolution historique des acronymes de prise en charge aiguë ?","o":["RICE → PRICE → POLICE → PEACE & LOVE","PEACE & LOVE → POLICE → PRICE → RICE","POLICE → RICE → PRICE → PEACE & LOVE","RICE → HARM → POLICE → PEACE & LOVE"],"r":0,"e":"C'est l'évolution décrite dans le cours, en référence au BJSM 2019.","s":0},{"q":"Que désigne l'acronyme HARM ?","o":["Ce qu'il faut éviter en phase aiguë : chaleur, alcool, course, massage","Les quatre étapes de la réparation : hémostase, inflammation, prolifération, remodelage","Un protocole de renforcement : force, amplitude, rythme, maintien","Les signes de l'inflammation : chaleur, rougeur, douleur, œdème"],"r":0,"e":"HARM regroupe ce qu'il faut éviter en phase aiguë : chaleur, alcool, activités en charge et massage. HARM = Heat, Alcohol, Running activities, Massage.","s":0},{"q":"Quelles cellules déclenchent la néovascularisation en phase de réparation ?","o":["Les macrophages","Les ostéoclastes","Les mastocytes","Les chondrocytes"],"r":0,"e":"Les macrophages déclenchent le processus de néovascularisation.","s":0},{"q":"Quel est le rôle des myofibroblastes en phase de réparation ?","o":["Générer une force centripète qui réduit la zone à réparer","Détruire le tissu de granulation en fin de réparation","Assurer la minéralisation du cal osseux","Produire le liquide synovial de l'articulation"],"r":0,"e":"Ils adhèrent à la marge de la lésion et génèrent une force centripète qui contracte la zone lésée.","s":0},{"q":"Comment se caractérise le tissu de granulation ?","o":["Un état gélatineux, avec des fibrilles désorganisées","Un tissu lamellaire, avec des fibres parfaitement orientées","Un tissu cartilagineux, déjà minéralisé","Un tissu adipeux mature, riche en vaisseaux"],"r":0,"e":"Le tissu de granulation est gélatineux, avec des fibrilles désorganisées au niveau de la lésion.","s":0},{"q":"Quel principe s'applique au travail de force en phase de réparation ?","o":["Des charges sous-maximales, graduelles, dans l'amplitude disponible, sans douleur","Des charges maximales dès le premier jour, quelle que soit la douleur ressentie","Un travail exclusivement en amplitude extrême, pour étirer la cicatrice","Une vitesse d'exécution maximale, pour stimuler les fibroblastes"],"r":0,"e":"En réparation : mouvement sélectif, charges sous-maximales graduelles, ROM disponible, pain-free, vitesse lente et contrôlée.","s":0},{"q":"Quels tissus appartiennent au tissu conjonctif spécialisé ?","o":["Le sang","Le tissu osseux","Le tissu cartilagineux","Les ligaments","Le tissu adipeux"],"r":[0,1,2,4],"e":"Le tissu conjonctif spécialisé regroupe le sanguin, l'osseux, le cartilagineux, le lymphatique et l'adipeux. Les ligaments relèvent du tissu conjonctif proprement dit.","s":0},{"q":"Quelles sont les quatre fonctions du tissu conjonctif proprement dit ?","o":["Soutien","Remplissage","Défense","Nutrition","Contraction"],"r":[0,1,2,3],"e":"Soutien, remplissage, défense et nutrition. La contraction est le propre des tissus contractiles.","s":0},{"q":"Que contient la substance fondamentale (ou amorphe) de la matrice extracellulaire ?","o":["Eau, protéines, glucides et lipides","Fibres de collagène, élastine et réticuline","Fibroblastes, macrophages et mastocytes","Tropocollagène, calcium et phosphate"],"r":0,"e":"La substance amorphe est faite d'eau, de protéines, de glucides et de lipides. Les fibres (collagène, élastiques, réticulaires) en sont distinctes, et les cellules ne font pas partie de la matrice.","s":0},{"q":"Quelles fibres trouve-t-on dans la matrice extracellulaire du tissu conjonctif proprement dit ?","o":["Fibres élastiques","Fibres de collagène","Fibres réticulaires","Fibres musculaires lisses"],"r":[0,1,2],"e":"Élastiques, de collagène et réticulaires. Les fibres musculaires lisses appartiennent au tissu musculaire, pas à la matrice conjonctive.","s":0},{"q":"Le fibroblaste répond aux stimuli mécaniques. Quelle conséquence pratique en découle ?","o":["La mise en charge progressive oriente la qualité du tissu réparé","Le tissu cicatrise identiquement quelle que soit la sollicitation","Il faut immobiliser jusqu'au remodelage complet","Seuls les médicaments modifient la synthèse de collagène"],"r":0,"e":"Parce que le fibroblaste est mécanosensible, la sollicitation graduée pendant la réparation et le remodelage influence directement l'orientation des fibres et la qualité finale du tissu.","s":0},{"q":"Pourquoi le tissu cicatriciel ne reproduit-il pas exactement l'architecture d'origine ?","o":["Les fibroblastes ne reproduisent pas fidèlement l'architecture d'origine","Le collagène de type I est absent de la cicatrice, remplacé par du type III","La néovascularisation empêche toute organisation des fibres de collagène","Les cross-links ne se forment jamais dans une cicatrice, même ancienne"],"r":0,"e":"Les fibroblastes sont des cellules stables : ils reconstruisent mais n'ont pas toujours la capacité de restituer l'architecture exacte du tissu d'origine, d'où la fibrose. Ce sont des cellules stables, d'où la fibrose.","s":0},{"q":"Quel phénomène de la phase de réparation vise à réduire la surface à réparer ?","o":["La contraction de la zone par les myofibroblastes","La phagocytose des débris par les macrophages","L'épithélialisation de surface par les kératinocytes","La stress-relaxation du tissu sous charge constante"],"r":0,"e":"Les myofibroblastes adhèrent aux marges de la lésion et génèrent une force centripète qui rapproche les berges, diminuant la zone à réparer.","s":0},{"q":"Quel est le rôle de l'épithélialisation en phase de réparation ?","o":["Former une fine couche contre l'infection et pour contenir les fluides","Détruire les débris cellulaires et les fibres lésées par phagocytose","Créer les cross-links définitifs entre les fibres de collagène","Déclencher la néovascularisation de la zone lésée"],"r":0,"e":"L'épithélialisation est une prolifération cellulaire qui forme une fine couche protectrice : barrière contre l'infection et contention des fluides.","s":0},{"q":"Pendant la néovascularisation, quel élément est décrit comme essentiel ?","o":["L'immobilisation de la zone","La mise en charge maximale","Le massage profond","L'application de chaleur"],"r":0,"e":"La fiche précise que l'immobilisation de la zone est essentielle pendant la néovascularisation ; chaleur et massage font d'ailleurs partie de HARM.","s":0},{"q":"De quoi dépendent les caractéristiques finales du tissu lésé, en phase de remodelage ?","o":["L'équilibre synthèse-dégradation","L'orientation des fibres","Le tropocollagène","Des cross-links plus solides","La seule durée d'immobilisation"],"r":[0,1,2,3],"e":"Quatre déterminants : le turn over synthèse/dégradation, l'orientation des fibres, le tropocollagène et des cross-links plus solides.","s":0},{"q":"Quel objectif caractérise spécifiquement la phase de remodelage ?","o":["La réintégration fonctionnelle et sportive, sans récidive","Le contrôle de la réponse inflammatoire, dans la zone lésée","La stabilisation de la situation aiguë, après le traumatisme","La seule diminution de l'œdème, par la compression"],"r":0,"e":"Le remodelage vise la réintégration fonctionnelle, professionnelle et sportive, c'est-à-dire la prévention secondaire des récidives. La réintégration est aussi professionnelle.","s":0},{"q":"« Prévention secondaire », dans ce contexte, signifie :","o":["Éviter la récidive chez un patient déjà lésé","Éviter l'apparition d'une première lésion","Dépister une lésion asymptomatique","Limiter les séquelles d'un handicap installé"],"r":0,"e":"La prévention secondaire s'adresse à un patient déjà lésé : l'objectif est d'éviter que la lésion ne se reproduise.","s":0},{"q":"Quels critères autorisent la réintégration après une lésion des tissus mous ?","o":["Absence de douleur et/ou de mécanismes de compensation","Absence d'épanchement articulaire et d'œdème","Mobilité fonctionnelle complète et symétrique","Retour au niveau de performance antérieur dès la première séance"],"r":[0,1,2],"e":"Trois critères : plus de douleur ni de compensation, plus d'épanchement ni d'œdème, et une mobilité fonctionnelle complète et symétrique.","s":0},{"q":"Quels éléments font partie des critères de prévention avant le retour au sport ?","o":["Force pré-lésionnelle retrouvée","Ratios agonistes-antagonistes","Stabilité articulaire normale","Travail pliométrique réalisé","Confiance psychologique","Disparition de la douleur seule"],"r":[0,1,2,3,4],"e":"Les cinq sont cités : force pré-lésionnelle, ratios agonistes/antagonistes, stabilité articulaire, pliométrie et confiance psychologique — à quoi s'ajoute le maintien de la condition physique.","s":0},{"q":"Un patient présente une douleur d'installation progressive, sans traumatisme identifiable, apparue après une augmentation de sa charge d'entraînement. De quel type de lésion s'agit-il ?","o":["Microtraumatique","Macrotraumatique","Lésion capsulaire aiguë","Rupture complète"],"r":0,"e":"Surcharge répétitive et installation progressive signent la lésion microtraumatique, par opposition au macrotraumatisme aigu à douleur et incapacité immédiates.","s":0},{"q":"Quelle est la différence entre le creep et la stress-relaxation ?","o":["Le creep se produit sous force constante, la stress-relaxation sous déformation constante","Le creep se produit sous déformation constante, la stress-relaxation sous force constante","Les deux se produisent sous force constante","Le creep est instantané, la stress-relaxation est différée"],"r":0,"e":"Creep : déformation progressive sous une force constante. Stress-relaxation : diminution de la force nécessaire pour maintenir une déformation constante. Les deux caractérisent la viscoélasticité.","s":0},{"q":"Un tissu subit une déformation de 6 %. Que peut-on en attendre ?","o":["Des micro-lésions : on dépasse 4 % sans atteindre 8 %","Aucune lésion : on reste sous le seuil de 8 %","Des macro-lésions : on dépasse le seuil de 4 %","Une rupture complète : on dépasse le seuil de 6 %"],"r":0,"e":"Les micro-lésions apparaissent dès 4 % de déformation ; les macro-lésions à partir de 8 %. À 6 % on est donc dans la zone de micro-lésions.","s":0},{"q":"Pourquoi le massage est-il déconseillé en phase inflammatoire aiguë (HARM) ?","o":["Il augmente la vascularisation et l'œdème d'une zone hyperperméable","Il détruit les cross-links néoformés et fragilise la cicatrice","Il empêche la phagocytose des débris par les macrophages","Il provoque une stress-relaxation excessive du tissu lésé"],"r":0,"e":"HARM = Heat, Alcohol, Running, Massage. Ces quatre éléments augmentent le débit sanguin et l'œdème alors que la perméabilité vasculaire est déjà accrue.","s":0},{"q":"Quels objectifs sont poursuivis en phase de réparation ?","o":["Diminuer la douleur et l'œdème","Augmenter le ROM, la force et la flexibilité","Rééduquer le système sensori-moteur","Normaliser le ratio force/flexibilité","Obtenir d'emblée des charges maximales"],"r":[0,1,2,3],"e":"La phase de réparation combine antalgie, gain de mobilité/force/flexibilité, rééducation sensori-motrice et normalisation du ratio force/flexibilité. Les charges y restent sous-maximales et graduelles.","s":0},{"q":"Comment doivent être appliquées les résistances en phase de réparation ?","o":["Sous-maximales, graduelles, dans l'amplitude, sans douleur, lentes","Maximales dès que la douleur a disparu, quelle que soit l'amplitude","En amplitude complète, quelle que soit la limitation et la douleur","À vitesse rapide, pour stimuler davantage les fibroblastes"],"r":0,"e":"Le principe est : charges sous-maximales appliquées graduellement, dans le ROM disponible, pain-free, à vitesse lente et contrôlée.","s":0},{"q":"Quelle est l'incidence des lésions musculo-squelettiques parmi tous les traumatismes en médecine du sport ?","o":["10 % à 55 %","1 % à 5 %","60 % à 90 %","Moins de 1 %"],"r":0,"e":"Maffulli et al. (2014) rapportent une incidence de 10 à 55 % de toutes les lésions.","s":1},{"q":"Combien de personnes dans le monde vivent avec des conditions musculo-squelettiques selon l'OMS (2022) ?","o":["Environ 1,71 milliard","Environ 170 millions","Environ 17 millions","Environ 500 millions"],"r":0,"e":"L'OMS estime ce chiffre à approximativement 1,71 milliard de personnes.","s":1},{"q":"Quels sont les trois muscles les plus fréquemment touchés ?","o":["Quadriceps, ischio-jambiers, gastrocnémiens","Deltoïde, trapèze supérieur, grand dorsal","Psoas, carré des lombes, diaphragme","Supra-épineux, biceps brachial, triceps"],"r":0,"e":"Le trio classique est quadriceps, ischio-jambiers et gastrocnémiens ; viennent ensuite adducteurs, supra-épineux et longue portion du biceps.","s":1},{"q":"La lacération musculaire relève de quel mécanisme ?","o":["Traumatisme direct","Traumatisme indirect","Fatigue musculaire","Myalgie d'effort"],"r":0,"e":"Ruptures, contusions et lacérations relèvent du traumatisme direct.","s":1},{"q":"La myalgie d'effort relève de quel mécanisme ?","o":["Traumatisme indirect","Traumatisme direct","Contusion","Lacération"],"r":0,"e":"Fatigue musculaire, myalgie d'effort et ruptures musculaires figurent parmi les mécanismes indirects.","s":1},{"q":"Quel est l'objectif de l'évolution des classifications des lésions musculaires ?","o":["Améliorer la capacité pronostique de la lésion","Réduire le coût de l'imagerie musculaire","Simplifier le codage administratif des lésions","Remplacer l'examen clinique par l'imagerie"],"r":0,"e":"Toutes les classifications successives visent à mieux prédire l'évolution et le délai de retour au jeu.","s":1},{"q":"En quelle année a été publié le Consensus de Munich ?","o":["2012","2014","2018","2008"],"r":0,"e":"Munich 2012, BAMIC 2014, MLG-R 2018.","s":1},{"q":"Que signifie BAMIC ?","o":["British Athletic Muscle Injury Classification","Barcelona Muscle Injury Classification","Basic Assessment of Muscle Injury Criteria","British Assessment of Musculoskeletal Injury Care"],"r":0,"e":"BAMIC = British Athletic Muscle Injury Classification (Pollock et al., BJSM 2014).","s":1},{"q":"De quel groupe provient la classification MLG-R ?","o":["Barcelona Innovation Hub","British Athletics","Consensus de Munich","FIFA Medical Network"],"r":0,"e":"La MLG-R (2018) est issue du Barcelona Innovation Hub.","s":1},{"q":"Comment distingue-t-on lésion fonctionnelle et lésion structurelle ?","o":["Seule la structurelle est visible à l'imagerie","La fonctionnelle est toujours plus grave que la structurelle","La structurelle ne provoque jamais aucune douleur à l'effort","La distinction repose sur la seule durée, en jours"],"r":0,"e":"Fonctionnelle = sans lésion visible à l'imagerie ; structurelle = avec lésion visible.","s":1},{"q":"Dans quel délai maximal les DOMS peuvent-ils survenir après l'effort ?","o":["Jusqu'à 72 h","Jusqu'à 12 h","Jusqu'à 7 jours","Immédiatement uniquement"],"r":0,"e":"Les DOMS peuvent apparaître jusqu'à 72 h après l'effort.","s":1},{"q":"Quel est le pic de symptomatologie le plus typique des DOMS ?","o":["24 à 48 h après l'effort","2 à 4 h après l'effort","5 à 7 jours après l'effort","Pendant l'effort"],"r":0,"e":"Le pic est variable d'une personne à l'autre mais typiquement situé entre 24 et 48 h.","s":1},{"q":"À quel type de la classification de Munich correspondent les DOMS ?","o":["Type 1b","Type 2a","Type 3a","Type 4"],"r":0,"e":"Les DOMS sont classés comme lésion musculaire de type 1b.","s":1},{"q":"Quel type de contraction prédomine dans la survenue des DOMS ?","o":["Les contractions excentriques","Les contractions isométriques","Les contractions concentriques","Les contractions isocinétiques"],"r":0,"e":"Les DOMS sont plus fréquents avec une prédominance de contractions excentriques, après une pause ou de nouveaux exercices.","s":1},{"q":"Dans les DOMS, la rupture des bandes Z prédomine dans quel type de fibres ?","o":["Les fibres rapides, de type 2","Les fibres lentes, de type 1","Les fibres myocardiques, du cœur","Les fibres musculaires lisses"],"r":0,"e":"La rupture des bandes Z prédomine dans les fibres de type II.","s":1},{"q":"Quelle stratégie ne figure PAS parmi les interventions proposées pour les DOMS ?","o":["Renforcement excentrique maximal","Massage","Pressothérapie","Cryothérapie ou bains de contraste"],"r":0,"e":"Les stratégies retenues sont mobilité, flexibilité, massage, pressothérapie, cryothérapie et bains de contraste.","s":1},{"q":"Quelle est l'évolution habituelle des DOMS ?","o":["Bénigne, en quelques jours","Chronique, dans la majorité des cas","Vers une rupture structurelle","Vers une myosite ossifiante"],"r":0,"e":"Le cours précise que l'évolution est bénigne.","s":1},{"q":"Dans une lésion musculaire « mineure », quel est l'état du ROM ?","o":["Complet","Diminué de moitié","Totalement aboli","Augmenté"],"r":0,"e":"La lésion mineure touche quelques fibres : douleur au mouvement actif mais ROM complet.","s":1},{"q":"Quel signe caractérise une lésion de plus de 50 % des fibres ?","o":["Une perte totale d'amplitude et une contraction impossible","Une amplitude complète et une douleur légère, à l'étirement","Une absence de déformation et d'hématome","Une douleur uniquement nocturne, au repos"],"r":0,"e":"Au-delà de 50 % : douleur intense au moment de la lésion, perte totale de ROM, incapacité à la contraction, déformation marquée.","s":1},{"q":"Quel mécanisme est typiquement associé aux lésions du quadriceps ?","o":["La décélération","L'accélération","L'immobilisation prolongée","La contraction isométrique lente"],"r":0,"e":"Accélération surtout pour les ischio-jambiers, décélération surtout pour le quadriceps.","s":1},{"q":"Quel mécanisme est typiquement associé aux lésions des ischio-jambiers ?","o":["L'accélération","La décélération","La flexion passive lente","La contraction excentrique du quadriceps"],"r":0,"e":"L'accélération est le mécanisme prédominant pour les ischio-jambiers.","s":1},{"q":"Quelle population est typiquement touchée par les lésions des jumeaux et du soléaire ?","o":["Les athlètes d'âge moyen et récréatifs","Les enfants de moins de dix ans, à l'école","Les personnes âgées alitées, sans activité","Les nageurs de haut niveau, exclusivement"],"r":0,"e":"Ces lésions sont prévalentes chez les athlètes d'« âge moyen » et récréatifs, lors d'activités balistiques en décélération.","s":1},{"q":"Quelle insertion figure parmi les avulsions myotendineuses les plus fréquentes ?","o":["L'insertion proximale du droit fémoral","L'insertion distale du deltoïde sur l'humérus","L'insertion distale du trapèze sur la scapula","L'insertion du muscle temporal sur la mandibule"],"r":0,"e":"Les plus fréquentes : insertion proximale du droit fémoral, proximale des IJ, long adducteur, distale du semi-tendineux.","s":1},{"q":"Quel objectif relève de la phase de remodelage dans les lésions musculaires ?","o":["Prévenir la kinésiophobie et préparer le geste sportif","Résorber l'œdème initial par la compression et l'élévation","Prévenir l'aggravation de la lésion dans les premiers jours","Déclencher la néovascularisation de la zone lésée"],"r":0,"e":"Le remodelage vise la normalisation de la fonction, la préparation au geste sportif et la prévention de la récidive et de la kinésiophobie.","s":1},{"q":"Quand la chirurgie est-elle indiquée dans les lésions musculaires ?","o":["En cas de lésion totale ou d'avulsion","Dès le grade mineur, pour gagner du temps","Systématiquement chez le sportif professionnel","En cas de courbatures persistantes après l'effort"],"r":0,"e":"Le traitement conservateur est le plus fréquent ; la chirurgie est réservée aux lésions totales et aux avulsions.","s":1},{"q":"Quelle stratégie post-opératoire est recommandée après suture musculaire ?","o":["Mobilisation précoce et contractions isométriques","Immobilisation stricte pendant trois mois","Charge maximale dès le premier jour post-opératoire","Massage profond de la cicatrice dès J1"],"r":0,"e":"On cherche à inverser les conséquences de l'immobilisation : PEACE & LOVE, mobilisation précoce, isométrie, charge progressive.","s":1},{"q":"Quelle est la caractéristique d'une contusion musculaire ?","o":["Un traumatisme direct, sans discontinuité structurelle","Une rupture complète des fibres, par un étirement brutal","Une lésion exclusivement indirecte, en course","Une absence totale d'épanchement et d'hématome"],"r":0,"e":"La contusion résulte d'un traumatisme direct, sans discontinuité structurelle, avec un possible épanchement associé.","s":1},{"q":"Que faut-il éviter en présence d'un hématome intramusculaire ?","o":["La compression et le massage","La cryothérapie locale","Le repos relatif du membre","L'élévation du membre"],"r":0,"e":"Compression et massage sont formellement contre-indiqués en présence d'un hématome intramusculaire.","s":1},{"q":"À quels muscles la myosite ossifiante est-elle le plus souvent associée ?","o":["Quadriceps et biceps","Deltoïde et trapèze","Psoas et iliaque","Soléaire et tibial antérieur"],"r":0,"e":"La myosite ossifiante est plus fréquente au quadriceps et au biceps, après chocs cycliques et contusions.","s":1},{"q":"Quel est le traitement du syndrome des loges aigu ?","o":["La fasciotomie en urgence","La cryothérapie seule","Les étirements de la loge","La modification de l'activité"],"r":0,"e":"La forme aiguë est une urgence chirurgicale : fasciotomie. Le traitement conservateur ne concerne que la forme chronique.","s":1},{"q":"Quels muscles figurent parmi les « autres localisations » touchées, en dehors du trio le plus fréquent ?","o":["Adducteurs de hanche","Supra-épineux","Longue portion du biceps","Gastrocnémiens"],"r":[0,1,2],"e":"Après quadriceps, ischio-jambiers et gastrocnémiens viennent les adducteurs de hanche, le supra-épineux et la longue portion du biceps.","s":1},{"q":"Quelles lésions relèvent d'un traumatisme direct ?","o":["Ruptures musculaires","Contusions","Lacérations","Myalgie d'effort"],"r":[0,1,2],"e":"Le traumatisme direct produit ruptures, contusions et lacérations. La myalgie d'effort et la fatigue musculaire relèvent du mécanisme indirect.","s":1},{"q":"Les ruptures musculaires apparaissent dans les deux colonnes de mécanismes. Qu'est-ce que cela signifie ?","o":["Une rupture survient aussi bien par choc direct que par sollicitation indirecte","La classification est erronée et doit être corrigée par le kinésithérapeute","Seul le mécanisme direct produit de vraies ruptures musculaires","Les ruptures indirectes sont toujours partielles, jamais complètes"],"r":0,"e":"Les ruptures musculaires figurent dans les deux colonnes : elles peuvent résulter d'un choc direct comme d'une sollicitation indirecte excessive.","s":1},{"q":"Dans quelles circonstances les DOMS sont-ils plus fréquents ?","o":["Après une pause prolongée","À l'introduction de nouveaux exercices","Avec une prédominance de contractions excentriques","Lors d'un travail isométrique de faible intensité"],"r":[0,1,2],"e":"Reprise après pause, nouveaux exercices et travail excentrique sont les trois situations favorisantes.","s":1},{"q":"Quels signes et symptômes accompagnent les DOMS ?","o":["Douleurs post-exercice","Raideur musculaire","Œdème","Perte de force","Déformation du muscle"],"r":[0,1,2,3],"e":"Douleur, raideur, œdème et perte de force. Une déformation visible évoquerait une lésion structurelle, pas des DOMS.","s":1},{"q":"Quels mécanismes physiopathologiques sont impliqués dans les DOMS ?","o":["Rupture des bandes Z","Accumulation de lactate","Altérations enzymatiques","Inflammation locale","Rupture myo-tendineuse"],"r":[0,1,2,3],"e":"Les DOMS sont multifactoriels : rupture des bandes Z (fibres de type II), lactate, altérations enzymatiques et inflammation.","s":1},{"q":"Quelles interventions kinésithérapiques sont proposées face aux DOMS ?","o":["Mobilité, flexibilité","Massage","Pressothérapie","Cryothérapie, bains de contraste","Excentrique maximal immédiat"],"r":[0,1,2,3],"e":"Mobilité, flexibilité, massage, pressothérapie, cryothérapie ou bains de contraste. Réintroduire immédiatement de l'excentrique maximal aggraverait les symptômes.","s":1},{"q":"Qu'est-ce qui définit une lésion musculaire structurelle ?","o":["Une perte de continuité de la fibre, visible à l'imagerie","Une douleur retardée, sans aucune anomalie à l'imagerie","Une simple accumulation de lactate, après un effort intense","Un œdème isolé, sans douleur ni perte de force"],"r":0,"e":"La lésion structurelle est définie par la perte de continuité de la fibre, avec possible discontinuité de la jonction myo-tendineuse — et elle est visible à l'imagerie. La perte de continuité peut toucher la jonction myo-tendineuse.","s":1},{"q":"Un patient a une douleur au mouvement actif mais un ROM complet, avec quelques fibres discontinues. Quel est le degré de gravité ?","o":["Lésion « mineure »","Lésion < 50 %","Lésion > 50 %","Avulsion myo-tendineuse"],"r":0,"e":"Perte de continuité de quelques fibres, douleur au mouvement actif et ROM complet définissent la lésion mineure.","s":1},{"q":"Quels signes accompagnent une lésion de moins de 50 % des fibres ?","o":["Douleur à la contraction","Perte d'amplitude","Déformation","Hémorragie","Contraction impossible"],"r":[0,1,2,3],"e":"Douleur à la contraction active, perte de ROM, déformation et hémorragie. L'incapacité totale de contraction signe plutôt une lésion > 50 %.","s":1},{"q":"Quel mécanisme est typique des lésions des jumeaux et du soléaire ?","o":["Des activités balistiques en décélération, avec sensation d'un coup reçu","Un traumatisme direct en compression, par un adversaire, au mollet","Un étirement lent et progressif, en fin d'amplitude, au repos","Une contraction isométrique prolongée, en position debout"],"r":0,"e":"Basket, football, course, sauts, en décélération ; le patient croit souvent avoir reçu un coup ou un projectile.","s":1},{"q":"Quelles insertions figurent parmi les avulsions myo-tendineuses les plus fréquentes ?","o":["Proximale du droit fémoral","Proximale des ischio-jambiers","Long adducteur","Distale du semi-tendineux","Distale du gastrocnémien médial"],"r":[0,1,2,3],"e":"Quatre insertions citées : proximale du droit fémoral, proximale des IJ, long adducteur et distale du semi-tendineux.","s":1},{"q":"Quels sont les objectifs de la phase inflammatoire dans une lésion musculaire ?","o":["Prévenir l'aggravation de la lésion","Favoriser vascularisation, résorption et alignement","Prévenir les troubles du timing et l'atrophie","Préparer immédiatement le geste sportif"],"r":[0,1,2],"e":"Prévenir l'aggravation, créer un meilleur contexte de réparation et prévenir les dysfonctions d'activation et l'atrophie. La préparation au geste sportif relève du remodelage.","s":1},{"q":"Quel objectif appartient à la phase de réparation dans une lésion musculaire ?","o":["Améliorer le contrôle neuromusculaire et la force, vers la fonction","Prévenir la kinésiophobie et la récidive, avant la reprise du sport","Prévenir l'aggravation de la lésion, dans les premiers jours","Réaliser une fasciotomie de décompression, en urgence"],"r":0,"e":"La réparation vise l'alignement des fibres, la qualité de contraction et de mouvement, le contrôle neuromusculaire et la force, en préparation de l'objectif fonctionnel.","s":1},{"q":"Pourquoi la prévention de la kinésiophobie figure-t-elle parmi les objectifs du remodelage ?","o":["L'appréhension du mouvement favorise les compensations et la récidive","Elle accélère la formation du collagène dans la cicatrice","Elle remplace le renforcement musculaire en fin de rééducation","Elle constitue un critère d'imagerie pour la reprise du sport"],"r":0,"e":"La phase de remodelage vise la normalisation de la fonction : éduquer à la qualité du mouvement et lever l'appréhension limite les compensations et donc les récidives.","s":1},{"q":"Quelles stratégies post-opératoires sont recommandées après chirurgie musculaire ?","o":["Inverser les effets de l'immobilisation","PEACE & LOVE, dès la phase aiguë","Mobilisation précoce douce","Isométrie, activation musculaire","Immobilisation stricte prolongée"],"r":[0,1,2,3],"e":"Lutter contre les effets de l'immobilisation, PEACE & LOVE, mobilisation précoce, isométrie/activation, puis introduction progressive de la charge.","s":1},{"q":"Que faut-il éviter lors de l'évaluation d'une contusion musculaire ?","o":["La contraction et l'étirement maximaux","Toute contraction active","La palpation","L'interrogatoire sur le mécanisme"],"r":0,"e":"On vérifie la fonction active mais on évite la contraction et l'étirement maximaux, qui risquent d'aggraver la lésion.","s":1},{"q":"Quel est le mécanisme de la myosite ossifiante ?","o":["Des chocs répétés, avec dépôts calciques et éperon osseux","Une infection bactérienne du corps musculaire, avec abcès","Une dégénérescence du collagène de type I, avec l'âge","Une compression nerveuse chronique, avec atrophie"],"r":0,"e":"Chocs cycliques et contusions répétés → accumulation de petits dépôts calciques entre les fibres, avec formation d'un éperon à partir de l'os sous-jacent. Les dépôts se forment entre les fibres et l'éperon part de l'os sous-jacent.","s":1},{"q":"Comment détecte-t-on une myosite ossifiante ?","o":["Par radiographie et/ou échographie de bonne définition","Par un bilan sanguin isolé, avec les enzymes musculaires","Par un test musculaire manuel, coté de 0 à 5","Par l'électromyographie seule, au repos et à l'effort"],"r":0,"e":"Radiographie et/ou échographie de bonne définition permettent de visualiser les dépôts calciques.","s":1},{"q":"Quelle est la prise en charge du syndrome des loges chronique ?","o":["Conservatrice d'abord, puis fasciotomie en cas d'échec","Fasciotomie en urgence, de façon systématique","Immobilisation plâtrée pendant six semaines, puis reprise","Abstention thérapeutique et simple surveillance"],"r":0,"e":"La forme chronique se traite d'abord de façon conservatrice ; la chirurgie n'intervient qu'en cas d'échec. C'est la forme aiguë qui impose la fasciotomie en urgence. Le traitement conservateur associe modification de l'activité, cryothérapie et étirements de la loge.","s":1},{"q":"Quelle affirmation décrit correctement la vascularisation du tendon ?","o":["Le tendon est peu vascularisé, et le pronostic dépend de la zone","Le tendon est richement vascularisé sur toute sa longueur, comme le muscle","Le tendon n'a aucune vascularisation, même à la jonction musculaire","La vascularisation est identique dans les trois tiers du tendon"],"r":0,"e":"Le tendon est peu vascularisé ; le pronostic de récupération est très influencé par la zone de la lésion.","s":2},{"q":"D'où proviennent les vaisseaux du premier tiers du tendon ?","o":["Du périmysium","Du paratendon","De la synoviale","De l'os"],"r":0,"e":"Dans le 1/3, les vaisseaux viennent du périmysium et pénètrent la structure tendineuse.","s":2},{"q":"Quel tissu explique l'absence de connexion directe entre les vaisseaux à la jonction tendon-os ?","o":["Le tissu fibrocartilagineux","Le tissu adipeux de Hoffa","Le tissu synovial de la gaine","Le périoste de l'os d'insertion"],"r":0,"e":"L'abondance et la désorganisation du tissu fibrocartilagineux empêchent les vaisseaux de se connecter directement entre eux.","s":2},{"q":"Quelle est la définition de la tendinite ?","o":["Inflammation aiguë et primaire du paratendon","Dégénérescence du tendon sans inflammation","Rupture complète du tendon","Calcification du corps musculaire"],"r":0,"e":"La tendinite est une inflammation aiguë et primaire du paratendon, avec ou sans altérations tissulaires.","s":2},{"q":"Quelle est la caractéristique histologique de la tendinose ?","o":["Des altérations dégénératives, sans signes inflammatoires","Un infiltrat inflammatoire massif, avec des polynucléaires","Des dépôts calciques constants, visibles à la radiographie","Une néovascularisation inflammatoire aiguë, très douloureuse"],"r":0,"e":"La tendinose correspond à des altérations dégénératives sans signes cliniques ni histologiques de réponse inflammatoire.","s":2},{"q":"Quelle conséquence la tendinose chronique a-t-elle sur le tendon ?","o":["Un collagène désorganisé et une prédisposition aux ruptures","Un collagène renforcé et une meilleure résistance à la charge","Une cellularité augmentée et une cicatrisation accélérée","Une guérison spontanée systématique, en quelques semaines"],"r":0,"e":"Dans la chronicité : perte de la structure normale du collagène, perte de cellularité, prédisposition aux ruptures.","s":2},{"q":"À quel moment la tendinopathie est-elle la lésion la plus commune ?","o":["En pré-saison et au retour après une pause","En milieu de saison, au pic de la compétition","Uniquement hors saison, pendant le repos","Pendant les phases d'immobilisation stricte"],"r":0,"e":"C'est explicitement la lésion la plus commune en pré-saison et/ou au retour après une pause.","s":2},{"q":"Qu'est-ce que la crépitation dans la tendinopathie ?","o":["Des adhérences du paratendon, lors du glissement","Un dépôt calcique audible, dans le tendon lui-même","Une rupture partielle des fibres, au moment de l'effort","Un épanchement articulaire, dans l'articulation voisine"],"r":0,"e":"La crépitation résulte des produits chimiques de l'inflammation accumulés, qui créent des adhérences du paratendon.","s":2},{"q":"Sur quelle structure osseuse s'insèrent les tendons de la coiffe des rotateurs ?","o":["Le trochiter, sous le bord externe de l'acromion","Le trochin, sous le bord antérieur de la clavicule","Le processus coracoïde, à sa face inférieure","L'épine de la scapula, à son bord supérieur"],"r":0,"e":"Les tendons de la coiffe s'insèrent sur le trochiter, immédiatement sous le bord externe de l'acromion.","s":2},{"q":"Quel type morphologique d'acromion augmente le risque de tendinopathie de la coiffe ?","o":["Le type III, crochu","Le type I, plat","Le type II, courbe","Aucun, la forme ne joue pas"],"r":0,"e":"La morphologie de type III favorise le pincement des tendons.","s":2},{"q":"Quel est l'arc douloureux caractéristique de la tendinopathie de la coiffe ?","o":["60° à 120° d'abduction","0° à 30° d'abduction","120° à 180° d'abduction","Il n'y a pas d'arc douloureux"],"r":0,"e":"L'arc douloureux typique se situe entre 60° et 120° d'abduction.","s":2},{"q":"Quel tendon est le plus souvent touché par la tendinopathie calcifiante de la coiffe ?","o":["Le supra-épineux","Le petit rond","Le sous-scapulaire","Le grand rond"],"r":0,"e":"Le dépôt de calcium se fait le plus fréquemment dans le tendon du supra-épineux.","s":2},{"q":"Quelle est la localisation de la douleur dans la tendinopathie calcifiante de l'épaule ?","o":["Face antéro-externe de l'épaule","Face postérieure de l'omoplate","Région cervicale basse","Face interne du bras uniquement"],"r":0,"e":"Douleur très intense de la face antéro-externe, nocturne, avec impotence fonctionnelle marquée.","s":2},{"q":"Dans l'épicondylite, quels mouvements résistés sont douloureux ?","o":["Extension et supination","Flexion et pronation","Abduction et rotation externe","Adduction et rotation interne"],"r":0,"e":"L'épicondylite touche les extenseurs : douleur en extension et supination résistées.","s":2},{"q":"Dans l'épitrochléite, quels mouvements résistés sont douloureux ?","o":["Flexion et pronation","Extension et supination","Abduction et rotation interne","Inclinaison latérale du poignet uniquement"],"r":0,"e":"L'épitrochléite touche les fléchisseurs : douleur en flexion et pronation résistées.","s":2},{"q":"Où se situe la douleur de l'épitrochléite ?","o":["À la face interne du coude et de l'avant-bras","À la face externe du coude et de l'avant-bras","À la face postérieure du bras, sur le triceps","À l'épaule, en regard du moignon"],"r":0,"e":"L'épitrochlée est médiale : douleur à la face interne du coude et de l'avant-bras.","s":2},{"q":"Quelle population est classiquement associée à l'épitrochléite ?","o":["Les golfeurs et les couturières","Les joueurs de tennis et les peintres","Les nageurs","Les coureurs de fond"],"r":0,"e":"Épitrochléite : golfeurs, femmes au foyer, couturières, travail sur ordinateur. Épicondylite : tennis, peintres.","s":2},{"q":"Quelle activité déclenche typiquement la douleur de la tendinopathie rotulienne ?","o":["Les sauts, la course, l'accroupissement et les escaliers","Le décubitus dorsal prolongé, jambes tendues sur le lit","La flexion cervicale prolongée, devant un écran d'ordinateur","La préhension forte, avec le poignet en extension"],"r":0,"e":"Douleur après sauts, course, accroupissement, montée et descente d'escaliers et position assise.","s":2},{"q":"Quel facteur de risque de la tendinopathie rotulienne est intrinsèque ?","o":["L'angle Q","Le type de chaussures","La qualité du sol","Le volume d'entraînement"],"r":0,"e":"Intrinsèques : âge, genre, angle Q, varus et valgus. Extrinsèques : entraînement, chaussures, sol.","s":2},{"q":"Quelle est la localisation la plus commune de la tendinopathie d'Achille ?","o":["Le tiers moyen et l'insertion","Le tiers proximal uniquement","La jonction myo-tendineuse haute","Le corps du gastrocnémien"],"r":0,"e":"Le début est graduel, plus commun au tiers moyen et à l'insertion.","s":2},{"q":"Quel symptôme est typique de la tendinopathie d'Achille ?","o":["Une raideur matinale qui s'améliore avec le mouvement","Une douleur qui n'apparaît qu'au repos complet, la nuit","Une paresthésie plantaire nocturne, qui réveille le patient","Un blocage articulaire brutal de la cheville, en flexion"],"r":0,"e":"Sensation de raideur matinale s'améliorant avec le mouvement, aggravée par la course en pente.","s":2},{"q":"Quel signe appartient à la phase chronique de la tendinopathie d'Achille ?","o":["Une crépitation et des raccourcissements de la chaîne postérieure","Un tendon chaud, douloureux et épaissi, comme en phase aiguë","Une rougeur cutanée intense, au-dessus du tendon","Un épanchement articulaire de la cheville"],"r":0,"e":"Phase aiguë : tendon chaud, douloureux, épaissi. Phase chronique : crépitation et raccourcissements adaptatifs.","s":2},{"q":"Quelle maladie métabolique constitue un facteur de risque intrinsèque de tendinopathie ?","o":["Le diabète","La bronchite chronique","La migraine","L'anémie ferriprive"],"r":0,"e":"Les maladies métaboliques citées sont le diabète, l'obésité et l'HTA.","s":2},{"q":"Quel est l'effet principal des exercices excentriques sur le tendon ?","o":["Favoriser la synthèse de collagène et le remodelage","Provoquer une inflammation aiguë qui relance la cicatrisation","Diminuer le flux sanguin local, pour réduire la douleur","Rompre les cross-links anciens, pour assouplir le tendon"],"r":0,"e":"L'excentrique favorise la synthèse de collagène, augmente le flux sanguin, diminue la douleur et favorise le remodelage.","s":2},{"q":"Pour quelles localisations les exercices isométriques à charges légères à modérées sont-ils particulièrement associés à l'amélioration de la douleur ?","o":["Coiffe des rotateurs et épicondylite","Tendon d'Achille et fascia plantaire","Tendon rotulien uniquement","Ténosynovite de De Quervain"],"r":0,"e":"Le cours cite une relation entre amélioration de la douleur et isométrique surtout pour la coiffe des rotateurs et l'épicondylite.","s":2},{"q":"Quel est le niveau de preuve du massage transverse profond (MTP) dans la tendinopathie d'Achille ?","o":["Sans preuve scientifique","Preuve de haut niveau","Traitement de première intention","Supérieur à l'exercice"],"r":0,"e":"Les preuves sont très faibles par rapport aux autres techniques, et absentes dans la tendinopathie d'Achille.","s":2},{"q":"Sur quelle durée la pharmacothérapie est-elle efficace sur la douleur tendineuse ?","o":["À court terme, sur 7 à 14 jours","À moyen terme, sur 3 à 6 mois","À long terme, de façon indéfinie","Sur aucune durée, elle est sans effet"],"r":0,"e":"Efficacité dans la diminution de la douleur à court terme (7-14 jours), surtout à l'épaule.","s":2},{"q":"Quels tendons sont concernés par la ténosynovite de De Quervain ?","o":["Long abducteur et court extenseur du pouce","Fléchisseur ulnaire et radial du carpe","Extenseur commun des doigts","Long palmaire et fléchisseur superficiel"],"r":0,"e":"Il s'agit d'une sténose des gaines du long abducteur et du court extenseur du pouce, au niveau de la styloïde radiale.","s":2},{"q":"À quelle période du post-partum la ténosynovite de De Quervain apparaît-elle fréquemment ?","o":["De la 4ᵉ à la 6ᵉ semaine après l'accouchement","Dans les 24 premières heures après l'accouchement","Après la première année qui suit l'accouchement","Pendant le dernier trimestre de la grossesse uniquement"],"r":0,"e":"Elle apparaît souvent de la 4ᵉ à la 6ᵉ semaine, probablement du fait d'altérations hormonales ou d'une rétention de liquides.","s":2},{"q":"Quels mouvements résistés sont douloureux dans la ténosynovite de la longue portion du biceps ?","o":["Flexion de l'épaule et supination","Extension de l'épaule et pronation","Abduction et rotation interne","Adduction horizontale"],"r":0,"e":"Douleur intense aux mouvements résistés de flexion de l'épaule et de supination, avec douleur à la palpation de la gouttière bicipitale.","s":2},{"q":"Quelles sont les fonctions principales du tendon ?","o":["Union os–muscle","Transmission et absorption des forces","Stabilité articulaire","Production active de la contraction"],"r":[0,1,2],"e":"Le tendon unit l'os au muscle, transmet et absorbe les forces et participe à la stabilité articulaire. Il ne se contracte pas lui-même.","s":2},{"q":"Quelles insertions le tendon présente-t-il ?","o":["Insertion ténopériostée","Insertion myotendineuse","Insertion capsulo-ligamentaire","Insertion synoviale"],"r":[0,1],"e":"Le tendon présente une insertion ténopériostée (côté os) et une insertion myotendineuse (côté muscle).","s":2},{"q":"Quel tiers du tendon est le mieux vascularisé ?","o":["Le tiers moyen, irrigué par le paratendon et la synoviale","Le tiers proximal, irrigué par le muscle et le périmysium","Le tiers d'insertion, irrigué par l'os et le périoste","Les trois tiers, irrigués de façon strictement équivalente"],"r":0,"e":"Dans les zones soumises à friction, le tiers moyen reçoit une irrigation du paratendon et de la structure synoviale : c'est la zone la mieux vascularisée. C'est le cas dans les zones soumises à friction.","s":2},{"q":"Pourquoi la zone de la lésion influence-t-elle fortement le pronostic tendineux ?","o":["Le tendon est peu vascularisé et l'irrigation varie selon le tiers","Le collagène est absent aux deux extrémités du tendon","Seule l'insertion osseuse contient des cellules vivantes","La douleur est toujours plus vive dans le tiers distal, près de l'insertion"],"r":0,"e":"Le tendon est globalement peu vascularisé et chaque tiers a une source d'irrigation différente : une lésion en zone mal vascularisée cicatrise moins bien.","s":2},{"q":"Quelles affirmations distinguent correctement tendinite et tendinose ?","o":["La tendinite comporte une inflammation, la tendinose non","La tendinose est tendanciellement asymptomatique","La tendinose prédispose aux ruptures","La tendinite touche primitivement le paratendon","La tendinose s'accompagne d'une inflammation histologique"],"r":[0,1,2,3],"e":"Tendinite : inflammation aiguë et primaire du paratendon, symptomatique. Tendinose : dégénérescence sans inflammation ni clinique ni histologique, souvent asymptomatique, qui prédispose aux ruptures.","s":2},{"q":"Quelles altérations caractérisent la chronicité de la tendinose ?","o":["Perte de la structure normale du collagène","Perte de cellularité","Infiltrat inflammatoire massif","Néovascularisation inflammatoire aiguë"],"r":[0,1],"e":"La tendinose chronique associe perte de la structure normale du collagène et perte de cellularité, sans réponse inflammatoire.","s":2},{"q":"Quels éléments composent le tableau clinique général d'une tendinopathie ?","o":["Douleur au mouvement","Œdème et fibrose","Crépitation","Recrutement moteur altéré","Fièvre et frissons"],"r":[0,1,2,3],"e":"Douleur au mouvement, œdème et fibrose, crépitation par adhérences du paratendon, et altération du recrutement moteur.","s":2},{"q":"Quelle disposition anatomique favorise le conflit dans la tendinopathie de la coiffe ?","o":["L'insertion sur le trochiter, juste sous l'acromion","L'insertion sur le trochin, au-dessus de l'acromion","Le passage dans la gouttière bicipitale, sous le ligament","L'insertion sur la glène, au pôle supérieur"],"r":0,"e":"Les tendons s'insèrent sur le trochiter immédiatement sous le bord externe de l'acromion, ce qui favorise le pincement contre la face inférieure de l'acromion et le ligament coraco-acromial.","s":2},{"q":"Quelles pathologies sont classiquement associées à la tendinopathie de la coiffe ?","o":["Syndrome de conflit sous-acromial","Bursite sous-acromiale","Tendinopathie calcifiante","Ténosynovite de De Quervain"],"r":[0,1,2],"e":"Conflit sous-acromial, bursite sous-acromiale et tendinopathie calcifiante. De Quervain concerne le poignet.","s":2},{"q":"Quels signes caractérisent la tendinopathie calcifiante de l'épaule ?","o":["Douleur nocturne avec troubles du sommeil","Signes inflammatoires marqués","Impotence fonctionnelle marquée, tout mouvement étant douloureux","Douleur strictement limitée à l'arc de 60° à 120°"],"r":[0,1,2],"e":"La forme calcifiante est très bruyante : douleur nocturne, inflammation marquée et impotence majeure — tout mouvement fait mal, à la différence de l'arc douloureux isolé.","s":2},{"q":"Un patient a mal à la face externe du coude, avec douleur au levage de charges et à la poignée de main. Quel diagnostic évoquez-vous ?","o":["Épicondylite","Épitrochléite","Ténosynovite de De Quervain","Tendinopathie bicipitale"],"r":0,"e":"Face externe, douleur au levage, au transport de charges, aux poignées de main et à la préhension : c'est l'épicondylite, confirmée par l'extension et la supination résistées.","s":2},{"q":"Où palpe-t-on l'insertion douloureuse dans l'épicondylite ?","o":["À l'insertion des extenseurs, juste sous l'épicondyle","À l'insertion des fléchisseurs, juste sous l'épitrochlée","Sur la gouttière bicipitale, à la face antérieure du bras","Sur la styloïde radiale, au bord externe du poignet"],"r":0,"e":"Épicondylite = tendons extenseurs, palpés juste sous l'épicondyle, sur la face externe.","s":2},{"q":"Quelles activités déclenchent typiquement la douleur d'une tendinopathie rotulienne ?","o":["Les sauts","La course","L'accroupissement","La montée et la descente d'escaliers","La position assise prolongée","La position allongée prolongée"],"r":[0,1,2,3,4],"e":"Toutes ces situations sont citées : sauts, course, accroupissement, escaliers et position assise.","s":2},{"q":"Quels facteurs extrinsèques favorisent la tendinopathie rotulienne ?","o":["Type, volume et qualité d'entraînement","Les chaussures","Le type de sol","Un angle Q élevé"],"r":[0,1,2],"e":"Entraînement, chaussures et sol sont extrinsèques. L'angle Q, comme l'âge, le genre, le varus et le valgus, est intrinsèque.","s":2},{"q":"Comment évolue la raideur matinale dans la tendinopathie d'Achille ?","o":["Elle s'améliore avec le mouvement","Elle s'aggrave avec le mouvement","Elle est constante toute la journée","Elle n'existe pas dans cette pathologie"],"r":0,"e":"Douleur localisée et raideur matinale qui s'améliore avec le mouvement : c'est un signe caractéristique. La douleur s'aggrave en revanche à la course en pente.","s":2},{"q":"Quels facteurs extrinsèques favorisent la tendinopathie d'Achille ?","o":["Surcharge","Geste technique sous-optimal","Changements brusques d'entraînement","Chaussures","Lésions antérieures","Prédisposition génétique"],"r":[0,1,2,3,4],"e":"Surcharge, technique, changements d'entraînement, chaussures et antécédents lésionnels. La génétique, les altérations biomécaniques et les maladies métaboliques sont intrinsèques.","s":2},{"q":"Quels sont les deux piliers de l'intervention kinésithérapique dans la tendinopathie ?","o":["La gestion du mouvement et de la charge","L'exercice thérapeutique","L'immobilisation prolongée","La chirurgie d'emblée"],"r":[0,1],"e":"Modification de l'activité et rééducation du schéma de mouvement d'une part, exercice (excentrique, concentrique contrôlé, isométrique) d'autre part.","s":2},{"q":"Quels moyens d'électrothérapie sont cités dans la tendinopathie ?","o":["Le LASER","Les ultrasons","Les ondes de choc","L'électrostimulation"],"r":[0,1,2],"e":"LASER, ultrasons et ondes de choc sont les trois moyens cités.","s":2},{"q":"Dans quelle localisation la pharmacothérapie est-elle la plus efficace sur la douleur tendineuse ?","o":["L'épaule","L'épicondyle","Le tendon d'Achille","Le tendon rotulien"],"r":0,"e":"La pharmacothérapie soulage à court terme (7 à 14 jours) et se montre plus efficace dans les tendinopathies de l'épaule que dans l'épicondylite ou la tendinopathie d'Achille.","s":2},{"q":"Qu'est-ce qui définit le doigt à ressaut (ténosynovite nodulaire) ?","o":["Un blocage de l'interphalangienne proximale, de la flexion à l'extension","Une sténose des gaines du pouce, en regard de la styloïde radiale","Une inflammation de la gouttière bicipitale, à la face antérieure du bras","Une rupture de la plaque palmaire de la métacarpo-phalangienne"],"r":0,"e":"Le doigt à ressaut se manifeste par un blocage, douloureux ou non, à l'interphalangienne proximale quand le doigt passe de la flexion à l'extension.","s":2},{"q":"Quelles sont les deux fonctions principales de la capsule et du ligament ?","o":["La nutrition de l'articulation et la stabilité articulaire","La production du mouvement et l'absorption des chocs","La conduction nerveuse et la vascularisation osseuse","L'hématopoïèse et la minéralisation de l'os sous-chondral"],"r":0,"e":"Le cours retient la nutrition/lubrification de l'articulation et la stabilité articulaire. La nutrition passe par la lubrification.","s":3},{"q":"Quel grade de lésion ligamentaire ne comporte PAS d'instabilité mécanique ?","o":["Le grade I","Le grade II","Le grade III","Aucun"],"r":0,"e":"Le grade I correspond à un étirement de certaines fibres avec douleur et œdème localisés, sans instabilité mécanique.","s":3},{"q":"Que caractérise une lésion ligamentaire de grade II ?","o":["Rupture partielle avec instabilité modérée","Rupture complète avec impotence totale","Simple étirement sans perte fonctionnelle","Absence d'œdème"],"r":0,"e":"Le grade II implique un traumatisme plus violent, une rupture partielle, une perte fonctionnelle partielle et une instabilité modérée.","s":3},{"q":"Quel est le mécanisme le plus fréquent de l'entorse de la tibio-tarsienne ?","o":["Inversion + flexion plantaire","Éversion + flexion dorsale","Rotation externe pure","Compression axiale"],"r":0,"e":"Inversion associée à la flexion plantaire est le mécanisme le plus fréquent.","s":3},{"q":"Quel test oriente vers une lésion de la syndesmose ?","o":["Le squeeze test","Le test de Lachman","Le test de Neer","Le signe du flot"],"r":0,"e":"Lésion de syndesmose : traumatisme à haute vitesse, douleur très intense, squeeze test positif.","s":3},{"q":"Quelle stratégie est particulièrement soulignée dans la prise en charge de l'entorse de cheville ?","o":["La rééducation sensori-motrice","L'immobilisation plâtrée de 6 semaines","Le massage profond immédiat","Le repos strict au lit"],"r":0,"e":"PEACE & LOVE, immobilisation sélective, force musculaire, RSM +++ et pliométrie.","s":3},{"q":"Quelle est la fonction du ligament croisé antérieur ?","o":["Contrôler l'antériorisation du tibia sous le fémur","Contrôler la postériorisation du tibia sous le fémur","Assurer la stabilité latérale du genou en varus","Transmettre les charges compressives au tibia"],"r":0,"e":"Le LCA contrôle l'antériorisation du tibia et stabilise l'articulation fémoro-tibiale.","s":3},{"q":"Quel mécanisme est typique de la lésion du LCA ?","o":["Un changement brusque de direction, pied fixé au sol","Une compression axiale lente, genou en extension","Un étirement passif prolongé, genou en flexion","Une contraction isométrique du quadriceps, assis"],"r":0,"e":"Mécanisme traumatique en pivot ; un mécanisme neurocognitif lié aux tâches multiples est également évoqué.","s":3},{"q":"Quelles lésions composent la « triade malheureuse » ?","o":["LCA + ménisque + LLI","LCA + LCP + LLE","Ménisque + LLE + rotule","LCA + rotule + tendon rotulien"],"r":0,"e":"L'association LCA, ménisque et ligament latéral interne constitue la triade malheureuse.","s":3},{"q":"Quelle affirmation sur la douleur dans la lésion du LCA est exacte ?","o":["Dans de nombreux cas, la douleur est absente","La douleur est toujours intense, permanente","La douleur est exclusivement nocturne, au repos","La douleur précède toujours le traumatisme"],"r":0,"e":"Le cours souligne que dans de nombreux cas la douleur n'est pas présente.","s":3},{"q":"Que signifie la sensation de « give away » ?","o":["Une dérobade du genou, signe d'instabilité","Un blocage articulaire complet du genou","Un craquement indolore, sans conséquence","Une raideur matinale, qui cède en une heure"],"r":0,"e":"Elle accompagne la claudication et traduit l'instabilité articulaire.","s":3},{"q":"Quels types de greffe sont utilisés dans la reconstruction du LCA ?","o":["Ischio-jambiers ou tendon rotulien","Tendon d'Achille ou fascia lata uniquement","Ligament synthétique exclusivement","Greffe osseuse iliaque"],"r":0,"e":"La greffe d'IJ ou de tendon rotulien conditionne les délais et les contre-indications.","s":3},{"q":"Dans quel cas privilégie-t-on un traitement conservateur du LCA ?","o":["Chez un patient peu actif ou indisponible pour la rééducation","Chez un athlète de haut niveau, avec des épisodes de dérobade","Chez un sujet jeune et sportif, avec une rupture totale du ligament","Chez un compétiteur, avec une instabilité majeure et une lésion associée"],"r":0,"e":"Le conservateur dépend de l'âge, des comorbidités, de l'absence d'activité sportive et de la disponibilité pour la rééducation.","s":3},{"q":"Quelle progression de force musculaire est proposée après reconstruction du LCA ?","o":["De l'isométrique d'abord, puis la chaîne ouverte et la chaîne fermée","De la pliométrie dès la première semaine, pour stimuler le greffon","Des charges maximales en chaîne ouverte dès la sortie de l'hôpital","Aucun travail de force avant six mois, pour protéger le greffon"],"r":0,"e":"FM isométrique en phase initiale puis évolution vers chaîne cinétique ouverte et fermée.","s":3},{"q":"Quelle est la fonction du LLI et du LLE ?","o":["La stabilité latérale de l'articulation du genou","Le contrôle de l'antériorisation du tibia sous le fémur","La transmission des charges axiales vers le tibia","La lubrification de l'articulation fémoro-tibiale"],"r":0,"e":"LLI (fémoro-tibial) et LLE (fémoro-fibulaire) assurent la stabilité latérale du genou.","s":3},{"q":"Quelles sont les fonctions des ménisques ?","o":["Congruence articulaire et transmission des charges","Production du liquide synovial et nutrition du cartilage","Stabilité latérale du genou en varus et en valgus","Contrôle de la seule rotation du fémur sur le tibia"],"r":0,"e":"Congruence articulaire et transmission des charges compressives, de cisaillement et axiales.","s":3},{"q":"Quelle partie du ménisque est la mieux vascularisée ?","o":["Le tiers externe, en zone rouge","Le tiers interne, en zone blanche","La corne postérieure, exclusivement","Toute la surface, de façon homogène"],"r":0,"e":"Le 1/3 externe (zone rouge) est le plus vascularisé ; les 2/3 restants sont nourris par diffusion passive liée à la charge axiale.","s":3},{"q":"Comment les 2/3 internes du ménisque sont-ils nourris ?","o":["Par diffusion passive, liée à la charge axiale","Par des artères propres, issues de la capsule","Par le liquide céphalo-rachidien, par voie sanguine","Ils ne sont pas nourris, et dégénèrent avec l'âge"],"r":0,"e":"Ils sont nourris par des processus de diffusion passive liés à la charge axiale.","s":3},{"q":"Quel facteur de risque figure parmi ceux des lésions méniscales ?","o":["Un surpoids important","Une grande taille","Le groupe sanguin","La latéralité"],"r":0,"e":"Les facteurs de risque cités sont l'âge, l'IMC et les lésions antérieures. Le surpoids s'évalue par l'IMC (indice de masse corporelle).","s":3},{"q":"Quelle classification n'appartient PAS aux lésions méniscales ?","o":["En anse de panier","Longitudinale","Radiale","En anse de seau"],"r":0,"e":"Les types sont : longitudinale, radiale, horizontale, oblique, en anse de seau et complexe.","s":3},{"q":"Dans quel cas la suture méniscale est-elle privilégiée ?","o":["Longitudinale, aiguë, périphérique, sujet jeune, ligaments intacts","Dégénérative, ancienne, sujet âgé, avec arthrose associée","Radiale, en zone blanche, mal vascularisée, chez l'adulte","Toute lésion méniscale, quels que soient le type et la zone"],"r":0,"e":"Ces critères définissent l'indication de la suture, dont le pronostic fonctionnel est supérieur à la méniscectomie.","s":3},{"q":"Quels sont les trois sites les plus touchés par l'instabilité chronique ?","o":["L'épaule, la tibio-tarsienne et la rotule","Le coude, le poignet et la hanche","Le rachis, la hanche et le genou","Les doigts, la mâchoire et le genou"],"r":0,"e":"Le cours cite l'épaule, la TT et la rotule.","s":3},{"q":"Quelle est la différence entre luxation et subluxation ?","o":["Dans la subluxation, l'os reprend tout de suite sa place","La subluxation est toujours opérée, contrairement à la luxation","La luxation ne touche jamais l'épaule, seulement la rotule","La subluxation ne donne jamais aucun symptôme ni douleur"],"r":0,"e":"Le mécanisme est semblable, mais dans la subluxation l'os reprend spontanément sa position.","s":3},{"q":"Quel type de luxation de l'épaule est le plus fréquent ?","o":["La luxation antérieure","La luxation postérieure","La luxation inférieure","La luxation supérieure"],"r":0,"e":"La luxation antérieure représente la grande majorité des cas.","s":3},{"q":"Qu'est-ce que la lésion de Bankart ?","o":["Une avulsion du labrum antéro-inférieur","Une empreinte osseuse de la tête humérale","Une rupture du supra-épineux","Une fracture de la glène postérieure"],"r":0,"e":"Bankart = avulsion du labrum antéro-inférieur sur lequel s'insère la bande antérieure du LGHI.","s":3},{"q":"À partir de quel pourcentage un défect de Hill-Sachs prédispose-t-il à l'instabilité ?","o":["Au-delà de 30 % de la surface articulaire","Au-delà de 10 % de la surface articulaire","Au-delà de 50 % de la surface articulaire","Au-delà de 5 % de la surface articulaire"],"r":0,"e":"Le défect prédispose à l'instabilité lorsqu'il dépasse 30 % de la surface articulaire humérale. Il s'agit de la surface articulaire de la tête humérale.","s":3},{"q":"Quand le traitement conservateur de l'instabilité gléno-humérale est-il privilégié ?","o":["Instabilité multidirectionnelle ou premier épisode sans autre risque","Sportif de haut niveau, avec des récidives invalidantes","Lésion de Bankart associée à une encoche de Hill-Sachs étendue","Systématiquement, quels que soient le profil et les récidives"],"r":0,"e":"La chirurgie est envisagée en 1ʳᵉ intention chez le compétiteur de haut niveau ou en cas de récidives invalidantes.","s":3},{"q":"Qu'est-ce que la capsulite rétractile ?","o":["Une fibrose rétractile qui empêche l'écartement des surfaces","Une inflammation de la bourse sous-acromiale, sous l'acromion","Une rupture du labrum supérieur, près de l'insertion du biceps","Une calcification du supra-épineux, visible à la radiographie"],"r":0,"e":"C'est une fibrose rétractile de l'articulation gléno-humérale. Elle touche l'articulation gléno-humérale.","s":3},{"q":"Quel est le profil épidémiologique typique de la capsulite rétractile ?","o":["Une femme de plus de 60 ans, avec une évolution de 1 à 2 ans","Un homme jeune et sportif, avec une évolution en 3 semaines","Un enfant de 10 ans, après une chute sur la main","Un adulte de 30 ans, après un traumatisme aigu seulement"],"r":0,"e":"Plus fréquente chez les femmes de plus de 60 ans, avec une évolution traînante jusqu'à 1 à 2 ans.","s":3},{"q":"Quel élément clinique distingue la capsulite rétractile ?","o":["Une limitation globale des mouvements actifs et passifs","Une limitation des seuls mouvements actifs, le passif restant libre","Une limitation de la seule abduction, les rotations restant libres","Une absence de douleur nocturne, même en décubitus du côté atteint"],"r":0,"e":"La limitation globale, active et passive, associée à une douleur nocturne intense en décubitus homolatéral, est caractéristique.","s":3},{"q":"Quels signes accompagnent une lésion ligamentaire de grade III ?","o":["Œdème important","Ecchymose","Grande instabilité","Impotence totale","Aucune instabilité"],"r":[0,1,2,3],"e":"Le grade III est une rupture complète : œdème important, ecchymose, grande instabilité et impotence fonctionnelle totale.","s":3},{"q":"Quelles populations sont particulièrement exposées à l'entorse de cheville ?","o":["Les sujets prédisposés à l'instabilité","Les sports à changements de direction","Les nageurs de fond, en piscine","Les cyclistes sur route, en peloton"],"r":[0,1],"e":"Instabilité ligamentaire préexistante et sports à changements de direction (tennis, padel, basket, football, handball).","s":3},{"q":"Quels signes et symptômes retrouve-t-on dans l'entorse de cheville ?","o":["Douleur","Œdème","Hématome","Marche impossible","Instabilité","Fièvre élevée"],"r":[0,1,2,3,4],"e":"Douleur, œdème, hématome, incapacité à la marche, instabilité et crépitation constituent le tableau.","s":3},{"q":"Qu'est-ce qui doit faire évoquer une lésion de la syndesmose plutôt qu'une entorse latérale simple ?","o":["Un traumatisme à haute vitesse, un squeeze test positif","Un œdème modéré du bord externe, sans aucune ecchymose","Une douleur nocturne isolée, sans aucun traumatisme récent","Une raideur matinale, qui cède après quelques pas"],"r":0,"e":"La lésion de syndesmose survient sur traumatisme à haute vitesse, avec une douleur très intense et un squeeze test positif. La douleur est aussi plus intense que dans l'entorse latérale.","s":3},{"q":"Quelles stratégies composent l'intervention dans l'entorse de cheville ?","o":["PEACE & LOVE","Immobilisation sélective","Force et sensori-motricité","Pliométrie","Plâtre de six semaines"],"r":[0,1,2,3],"e":"PEACE & LOVE, immobilisation sélective, force et RSM (particulièrement soulignée) puis pliométrie.","s":3},{"q":"Quel mécanisme récent est évoqué dans la survenue des lésions du LCA ?","o":["Un mécanisme neurocognitif lié aux tâches multiples en sport","Une origine strictement génétique, transmise dans la famille","Une carence en collagène de type I, d'origine nutritionnelle","Un mécanisme purement inflammatoire, sans traumatisme"],"r":0,"e":"Au-delà du pivot et du changement de direction, des données récentes suggèrent un mécanisme neurocognitif associé à la double tâche en sport.","s":3},{"q":"Dans quels sports la lésion du LCA est-elle fréquente ?","o":["Football","Ski","Natation","Cyclisme sur piste"],"r":[0,1],"e":"Sports avec sauts, changements rapides de direction et décélérations : football et ski sont cités.","s":3},{"q":"Que décrit le grade 1 d'une lésion du LCA ?","o":["Un ligament allongé, le genou restant stable","Une rupture partielle, avec une laxité modérée","Une rupture totale, avec une instabilité majeure","Une avulsion osseuse, au niveau de l'insertion tibiale"],"r":0,"e":"Grade 1 : le ligament est allongé mais maintient encore la stabilité du genou. Le grade 2 (rupture partielle) est le moins fréquent, le grade 3 est la rupture totale.","s":3},{"q":"Quels signes accompagnent fréquemment une rupture du LCA ?","o":["Sensation de claquement","Épanchement articulaire","Claudication et sensation de « give away »","Douleur systématiquement intense"],"r":[0,1,2],"e":"Claquement, épanchement, claudication et dérobement. La douleur, elle, est souvent absente.","s":3},{"q":"Quelles stratégies de kinésithérapie s'appliquent après reconstruction du LCA ?","o":["PEACE & LOVE, au début","Mobilité et cicatrice, selon les délais","Force, sensori-motricité, pliométrie","Éducation du patient","Pivot dès la deuxième semaine"],"r":[0,1,2,3],"e":"PEACE & LOVE, mobilité et travail de la cicatrice dans le respect des délais, force, RSM, pliométrie et éducation. Le type de greffe conditionne les délais.","s":3},{"q":"Quelles unions osseuses les ligaments latéraux du genou assurent-ils ?","o":["LLI : union fémoro-tibiale","LLE : union fémoro-fibulaire","LLI : union fémoro-fibulaire","LLE : union tibio-fibulaire"],"r":[0,1],"e":"Le LLI unit fémur et tibia, le LLE unit fémur et fibula. Ensemble ils assurent la stabilité latérale du genou.","s":3},{"q":"Quels examens participent au diagnostic d'une lésion du LLI ou du LLE ?","o":["Histoire clinique","Tests spécifiques","Radiographie","IRM","Électromyographie"],"r":[0,1,2,3],"e":"Histoire clinique, tests spécifiques, radiographie (pour les altérations osseuses associées à une contusion) et IRM.","s":3},{"q":"De quoi dépend le pourcentage de charge transmis par les ménisques ?","o":["Du degré de flexion du genou","De l'âge du patient","De l'IMC","De la vitesse du mouvement"],"r":0,"e":"Les ménisques assurent congruence et transmission des charges compressives, de cisaillement et axiales ; la part transmise varie selon le degré de flexion du genou.","s":3},{"q":"Quels mécanismes sont à l'origine des lésions méniscales ?","o":["Un mécanisme surtout dégénératif","Les grandes flexions du genou","Un traumatisme, en chaîne fermée","Une infection articulaire"],"r":[0,1,2],"e":"Essentiellement dégénératif, favorisé par les grandes flexions, et traumatique surtout en chaîne cinétique fermée.","s":3},{"q":"Quelles conditions réunit la suture méniscale idéale ?","o":["Lésion longitudinale","Lésion plutôt aiguë","Sujet jeune","Ligaments intacts","Zone périphérique","Lésion radiale étendue"],"r":[0,1,2,3,4],"e":"Les cinq conditions sont citées, et la suture offre alors un pronostic fonctionnel supérieur à la méniscectomie.","s":3},{"q":"Quelle stratégie est particulièrement soulignée dans la prise en charge des lésions méniscales ?","o":["L'éducation","L'électrothérapie","L'immobilisation stricte","La pharmacothérapie au long cours"],"r":0,"e":"L'éducation est marquée « +++ », avec PEACE & LOVE, mobilité, force musculaire et rééducation sensori-motrice.","s":3},{"q":"Quels sites sont typiquement concernés par la subluxation ?","o":["L'épaule","La rotule, surtout chez la femme","Le coude, chez l'enfant","Les doigts, au sport"],"r":[0,1],"e":"Subluxation : épaule et rotule (chez la femme). Coude et doigts sont cités pour la luxation.","s":3},{"q":"De quoi dépend la récupération après une luxation ?","o":["De l'étendue de la lésion des tissus mous voisins","De la seule rapidité de la réduction de la luxation","De l'âge du patient, exclusivement, quelle que soit la lésion","Du type d'anesthésie utilisé pour la réduction"],"r":0,"e":"La récupération dépend avant tout de l'étendue des lésions des tissus mous environnants.","s":3},{"q":"Quelles structures peuvent être en cause dans une instabilité gléno-humérale ?","o":["Le labrum","Le cartilage glénoïdien et huméral","Les ligaments et la capsule","La coiffe et le tendon du biceps","Le fascia plantaire"],"r":[0,1,2,3],"e":"Toutes ces structures sont citées comme causes possibles d'instabilité gléno-humérale.","s":3},{"q":"Quels sont les principes d'intervention dans la capsulite rétractile en phase aiguë ?","o":["Pharmacothérapie : anti-inflammatoires et corticoïdes","Thérapie manuelle, électrothérapie et exercices à visée antalgique","Manipulation sous anesthésie générale si nécessaire","Renforcement maximal immédiat en amplitude complète"],"r":[0,1,2],"e":"Anti-inflammatoires et corticoïdes en phase inflammatoire marquée, kinésithérapie antalgique, et manipulation sous anesthésie générale en recours chirurgical.","s":3},{"q":"Quelle est la fonction de la bourse séreuse ?","o":["Réduire le frottement des tendons sur l'os","Produire le collagène des tendons voisins","Assurer la contraction des muscles voisins","Transmettre l'influx nerveux aux muscles"],"r":0,"e":"C'est sa fonction mécanique principale. La bourse s'interpose entre tendon et relief osseux.","s":4},{"q":"Quelle bourse ne figure PAS parmi les plus fréquemment affectées ?","o":["La bourse sous-scapulaire","La bourse sous-acromiale","La bourse trochantérienne","La bourse pré-patellaire"],"r":0,"e":"Les plus touchées sont les bourses sous-acromiale, olécrânienne, trochantérienne, pré-patellaire et calcanéenne.","s":4},{"q":"Qu'est-ce qui irrite les nocicepteurs dans la bursite ?","o":["L'accumulation de liquide synovial","La calcification du tendon","La rupture des fibres musculaires","La compression nerveuse"],"r":0,"e":"L'inflammation provoque la production de grandes quantités de liquide synovial dont l'accumulation irrite les nocicepteurs locaux.","s":4},{"q":"Comment débute typiquement une bursite sous-acromiale ?","o":["De façon soudaine, avec des signes inflammatoires marqués","De façon progressive, sur plusieurs années, sans inflammation","Sans aucun symptôme, découverte à l'imagerie","Uniquement après 60 ans, chez le sujet sédentaire"],"r":0,"e":"Début soudain, signes inflammatoires marqués et impotence fonctionnelle totale avec postures antalgiques.","s":4},{"q":"Où se situe la douleur de la bursite trochantérienne en phase aiguë ?","o":["Intense et précise sur la face externe de la hanche","Diffuse dans tout le membre inférieur, jusqu'au pied","À la face antérieure du genou, sous la rotule","Dans la région inguinale, au pli de l'aine"],"r":0,"e":"En phase aiguë la douleur est intense et précise sur la face externe ; elle devient indéfinie et étendue dans la chronicité.","s":4},{"q":"Quels mouvements résistés reproduisent la douleur de la bursite trochantérienne ?","o":["Abduction et rotation externe","Adduction et rotation interne","Flexion et extension de genou","Flexion plantaire"],"r":0,"e":"Douleur à la palpation du bord supérieur du trochanter et aux mouvements résistés d'abduction et rotation externe.","s":4},{"q":"Le kyste de Baker correspond à l'atteinte de quelle bourse ?","o":["La bourse des gastrocnémiens et du semi-membraneux","La bourse pré-patellaire, en avant de la rotule","La bourse trochantérienne, en regard du grand trochanter","La bourse olécrânienne, en arrière du coude"],"r":0,"e":"C'est le remplissage ou l'inflammation de la bourse des gastrocnémiens/semi-membraneux, à la face postérieure du genou.","s":4},{"q":"Devant un kyste de Baker avec douleur sévère et œdème exacerbé du mollet, que faut-il écarter en urgence ?","o":["Une thrombose veineuse profonde","Une fracture de fatigue","Une rupture du LCA","Une bursite pré-patellaire"],"r":0,"e":"Il est urgent d'écarter une TVP et d'orienter vers les urgences.","s":4},{"q":"Quelle intervention kinésithérapique est proposée pour le kyste de Baker ?","o":["Une compression élastique et de l'isométrique du quadriceps","Un renforcement excentrique maximal des ischio-jambiers","Un massage profond de la fosse poplitée et du mollet","Une immobilisation plâtrée de trois semaines, genou tendu"],"r":0,"e":"Après aspiration éventuelle : compression par bande élastique et travail isométrique du quadriceps.","s":4},{"q":"Au-dessus de quel angle les mouvements répétitifs exposent-ils au conflit sous-acromial ?","o":["90°","30°","150°","45°"],"r":0,"e":"Ce sont les individus exécutant des mouvements répétitifs au-dessus de 90° qui sont concernés.","s":4},{"q":"Quel élément correspond à un conflit sous-acromial primaire ?","o":["Un acromion crochu","Une tendinopathie associée","Une bursite associée","Une rupture méniscale"],"r":0,"e":"Primaire : acromion type III, laxité capsulaire, déséquilibres de la coiffe, causes rhumatologiques. Secondaire : associé à tendinopathie ou bursite. L'acromion crochu correspond au type III.","s":4},{"q":"Vers quelle complication le conflit sous-acromial peut-il évoluer ?","o":["La rupture du tendon du supra-épineux","La capsulite rétractile obligatoire","La luxation postérieure","L'arthrose acromio-claviculaire isolée"],"r":0,"e":"L'évolution peut mener à une rupture de la coiffe / du supra-épineux, fréquente chez l'homme de plus de 50 ans.","s":4},{"q":"Après combien de temps d'échec du traitement conservateur l'acromioplastie est-elle envisagée ?","o":["6 mois","2 semaines","2 ans","6 semaines"],"r":0,"e":"L'acromioplastie est indiquée quand le traitement conservateur du conflit échoue après 6 mois.","s":4},{"q":"Quel est l'objectif de l'acromioplastie ?","o":["Augmenter l'espace sous-acromial","Réduire la mobilité de l'épaule","Fusionner l'articulation gléno-humérale","Retirer le labrum"],"r":0,"e":"L'objectif est l'augmentation de l'espace sous-acromial ; on peut y associer une réparation de la coiffe ou de la capsule.","s":4},{"q":"Où se situe la lésion SLAP ?","o":["Au labrum supérieur de la glène, près du long biceps","À la face inférieure de l'acromion, au-dessus de la coiffe","Sur le trochiter, à l'insertion du supra-épineux","Dans la gouttière bicipitale distale, au bras"],"r":0,"e":"SLAP = Superior Labrum Anterior Posterior, près de l'insertion de la longue portion du biceps. SLAP : Superior Labrum Anterior Posterior.","s":4},{"q":"Quelle perte d'amplitude est typique de la lésion SLAP ?","o":["La rotation interne","L'abduction pure","La flexion antérieure","L'extension en arrière"],"r":0,"e":"On observe une perte de ROM en rotation interne, associée à une perte de force de la coiffe.","s":4},{"q":"Quelle conduite s'applique à une lésion SLAP de type III ?","o":["La chirurgie","Le conservateur seul","L'abstention complète","L'immobilisation stricte"],"r":0,"e":"Type I : conservateur. Type II : chirurgie si échec du conservateur. Type III : chirurgie.","s":4},{"q":"Quel nerf est comprimé dans le syndrome du canal carpien ?","o":["Le nerf médian","Le nerf ulnaire","Le nerf radial","Le nerf musculo-cutané"],"r":0,"e":"Il s'agit de la compression du nerf médian lors de sa traversée du poignet.","s":4},{"q":"Quel examen confirme le diagnostic de syndrome du canal carpien ?","o":["L'électromyographie","La radiographie standard","L'échographie Doppler","La scintigraphie"],"r":0,"e":"Le diagnostic est confirmé par électromyographie.","s":4},{"q":"Comment évoluent les paresthésies du syndrome du canal carpien ?","o":["Nocturnes et matinales, elles cèdent dans la journée","Elles n'apparaissent qu'en fin de journée, après le travail","Elles sont permanentes dès le début, jour et nuit","Elles ne concernent que le pouce, sans les autres doigts"],"r":0,"e":"Paresthésies nocturnes et matinales qui cèdent au cours de la journée, avec perte de dextérité.","s":4},{"q":"Quelle condition n'est PAS un facteur associé au syndrome du canal carpien ?","o":["L'ostéoporose","La grossesse","Le diabète","La polyarthrite rhumatoïde"],"r":0,"e":"Les facteurs cités sont la grossesse, le diabète, la polyarthrite rhumatoïde, la goutte et l'arthrose.","s":4},{"q":"Quelle attelle est proposée dans le syndrome du canal carpien ?","o":["Une attelle de positionnement nocturne","Une attelle dynamique portée le jour","Un plâtre circulaire de l'avant-bras","Une orthèse plantaire sur mesure"],"r":0,"e":"Les attelles de positionnement nocturne font partie des stratégies d'intervention.","s":4},{"q":"Quelles situations aggravent le syndrome fémoro-patellaire ?","o":["Les escaliers et les longues périodes en position assise","Le décubitus dorsal prolongé, jambes tendues sur le lit","La marche en terrain plat uniquement, à vitesse lente","La flexion cervicale prolongée, devant un écran"],"r":0,"e":"Il s'aggrave dans les escaliers, au passage flexion-extension en charge et après de longues périodes assis.","s":4},{"q":"Qu'est-ce que le syndrome de la plica ?","o":["Un repli synovial qui ne régresse pas au stade embryonnaire","Une inflammation de la bourse pré-patellaire, après un choc","Une lésion du cartilage rotulien, par usure chronique","Une rupture partielle du tendon rotulien, chez le sauteur"],"r":0,"e":"C'est un repli synovial persistant, siège d'un processus inflammatoire idiopathique, macro- ou microtraumatique.","s":4},{"q":"Où se situe la douleur du syndrome de la bandelette ilio-tibiale ?","o":["Dans la zone latérale externe du genou","À la face antérieure du genou, sous la rotule","Dans le creux poplité, en arrière du genou","À la face interne de la cuisse, au-dessus du genou"],"r":0,"e":"Il s'agit d'un processus inflammatoire de la portion distale de la bandelette, avec douleur latérale externe.","s":4},{"q":"Quelle population est la plus concernée par le syndrome de la bandelette ilio-tibiale ?","o":["Les coureurs","Les nageurs","Les haltérophiles","Les joueurs de tennis"],"r":0,"e":"C'est une lésion commune chez les coureurs, liée à la friction et à l'irritation de la structure.","s":4},{"q":"Où s'insère le fascia plantaire dont l'inflammation cause la fasciite plantaire ?","o":["Sur le calcanéus, à l'arrière","Sur les têtes des métatarsiens","Sur le talus, à sa face inférieure","Sur le naviculaire, en dedans"],"r":0,"e":"Il s'agit de l'inflammation du fascia plantaire à son insertion postérieure sur le calcanéus. C'est l'insertion postérieure du fascia.","s":4},{"q":"Quand la douleur de la fasciite plantaire est-elle typiquement déclenchée ?","o":["À la mise en charge, surtout au réveil","Uniquement le soir, après la journée de travail","Pendant le sommeil, sans mise en charge","Au repos assis, pieds posés à plat"],"r":0,"e":"Douleur sous-calcanéenne déclenchée par la charge surtout au réveil, s'aggravant progressivement à la marche.","s":4},{"q":"Quel mouvement peut exacerber la douleur de la fasciite plantaire ?","o":["L'extension des orteils","La flexion du genou","La rotation de hanche","L'inversion du pied"],"r":0,"e":"L'extension des orteils met le fascia en tension et peut exacerber la douleur.","s":4},{"q":"Quels sont les types de conflit fémoro-acétabulaire ?","o":["CAM, Pincer ou mixte","Type I, II et III","Antérieur, postérieur, latéral","Primaire et secondaire uniquement"],"r":0,"e":"Le conflit fémoro-acétabulaire se décline en CAM, Pincer ou mixte ; c'est la dysfonction de hanche la plus fréquente du jeune adulte.","s":4},{"q":"Comment définit-on la biomécanique dans ce contexte ?","o":["L'interaction des forces internes et externes dans le mouvement","L'étude des seules forces musculaires, pendant le mouvement","La description anatomique des articulations et de leurs ligaments","L'analyse de la dépense énergétique du mouvement humain"],"r":0,"e":"La biomécanique est l'interaction des forces internes et externes mécaniques dans le mouvement humain.","s":4},{"q":"Pourquoi l'examen subjectif et objectif est-il central dans les dysfonctions biomécaniques ?","o":["Le mécanisme lésionnel est un déséquilibre de facteurs à identifier","Il remplace l'imagerie dans le diagnostic de ces dysfonctions","Il permet de chiffrer précisément la douleur ressentie par le patient","Il détermine la durée d'immobilisation nécessaire après la lésion"],"r":0,"e":"La lésion résulte d'un déséquilibre des facteurs internes et/ou externes : il faut donc les évaluer, d'où l'importance des examens subjectif et objectif. Ces facteurs sont internes et/ou externes.","s":4},{"q":"Quels mécanismes peuvent provoquer une bursite ?","o":["Traumatisme","Mouvements répétitifs et surcharge","Conditions rhumatologiques","Processus infectieux","Carence en vitamine D"],"r":[0,1,2,3],"e":"Les quatre mécanismes sont cités : traumatique, microtraumatique/surcharge, rhumatologique et infectieux.","s":4},{"q":"Quel est le tableau clinique d'une bursite ?","o":["Douleur sévère","Œdème de la bourse","Amplitudes très limitées","Paresthésies distales"],"r":[0,1,2],"e":"Douleur sévère, œdème de la bourse et limitation marquée des amplitudes. Les paresthésies évoquent une atteinte nerveuse.","s":4},{"q":"Quelles interventions sont proposées dans la bursite ?","o":["PEACE & love","Pharmacothérapie","Kinésithérapie","Éducation","Plâtre de six semaines"],"r":[0,1,2,3],"e":"PEACE & love, pharmacothérapie, kinésithérapie et éducation.","s":4},{"q":"Pourquoi un diagnostic différentiel est-il nécessaire entre bursite sous-acromiale et tendinopathie de la coiffe ?","o":["Leurs facteurs de risque et leur examen objectif se ressemblent","Elles ont exactement le même traitement chirurgical, l'acromioplastie","L'imagerie ne permet jamais de les distinguer l'une de l'autre","Elles touchent des tranches d'âge opposées, jeunes et âgés"],"r":0,"e":"Facteurs de risque et examen objectif sont semblables, d'où la nécessité d'un diagnostic différentiel.","s":4},{"q":"Comment évolue la douleur de la bursite trochantérienne vers la chronicité ?","o":["Elle devient diffuse, vers la fesse, la crête iliaque et la cuisse","Elle se limite progressivement au seul relief du grand trochanter","Elle disparaît la nuit, quelle que soit la position de couchage","Elle migre vers la face antérieure de la cuisse et vers l'aine"],"r":0,"e":"Précise et intense sur la face externe de hanche en phase aiguë, elle devient indéfinie et étendue dans la chronicité. Elle peut aussi gagner la face externe de la jambe.","s":4},{"q":"Quelles situations aggravent la douleur de la bursite trochantérienne ?","o":["La marche","Les rotations de hanche","Le décubitus homolatéral la nuit","La position assise prolongée"],"r":[0,1,2],"e":"Marche, rotations de hanche et décubitus homolatéral nocturne. Le syndrome fémoro-patellaire, lui, est aggravé par la position assise prolongée.","s":4},{"q":"À quelles lésions le kyste de Baker est-il associé ?","o":["Lésion méniscale","Lésion cartilagineuse","Maladies rhumatologiques","Rupture du LCA isolée"],"r":[0,1,2],"e":"Le kyste de Baker s'associe aux lésions dégénératives du genou : méniscale, cartilagineuse, et aux maladies rhumatologiques.","s":4},{"q":"Quels signes cliniques accompagnent un kyste de Baker ?","o":["Tension poplitée qui s'aggrave à la marche","Raideur matinale","Épanchement associé","Paresthésies du pied"],"r":[0,1,2],"e":"Tension poplitée aggravée à la marche, raideur matinale et épanchement. Les paresthésies ne font pas partie du tableau.","s":4},{"q":"Quel conflit sous-acromial est qualifié de secondaire ?","o":["Celui associé à une tendinopathie ou à des bursites","Celui lié à un acromion de type III, crochu","Celui lié à une laxité capsulaire de l'épaule","Celui d'origine rhumatologique, inflammatoire"],"r":0,"e":"Le conflit secondaire est associé à une tendinopathie ou à des bursites. Acromion type III, laxité capsulaire, déséquilibres de coiffe et causes rhumatologiques définissent le conflit primaire.","s":4},{"q":"Quels mouvements sont douloureux dans le conflit sous-acromial ?","o":["Flexion","Abduction","Adduction horizontale","Rotation interne","Extension de coude"],"r":[0,1,2,3],"e":"Flexion, abduction, adduction horizontale et rotation interne de l'épaule.","s":4},{"q":"Par quelles voies l'acromioplastie peut-elle être réalisée ?","o":["Arthroscopique","Ouverte","Percutanée","Postérieure"],"r":[0,1],"e":"L'acromioplastie se pratique par voie arthroscopique ou ouverte.","s":4},{"q":"Quels gestes peuvent être associés à une acromioplastie ?","o":["Réparation du tendon de la coiffe","Traitement de la bursite","Réparation de dommages capsulaires","Prothèse totale d'épaule"],"r":[0,1,2],"e":"Pendant la décompression, on peut réparer la coiffe, traiter la bursite ou réparer des dommages capsulaires.","s":4},{"q":"Quels mécanismes peuvent être à l'origine d'une lésion SLAP ?","o":["Dégénératif, avec Bankart ou coiffe, après 40 ans","Instabilité antérieure de l'épaule","Lésion du long chef du biceps","Surcharge par gestes répétés au-dessus de la tête","Compression du nerf médian au poignet"],"r":[0,1,2,3],"e":"Quatre mécanismes : dégénératif, instabilité antérieure, lésion de la longue portion du biceps et surcharge.","s":4},{"q":"Quels signes composent le tableau clinique d'une lésion SLAP ?","o":["Douleur lors des mouvements au-dessus de la tête","Sensation de « clic » avec inconfort","Perte de ROM en rotation interne","Perte de force des muscles de la coiffe","Difficulté à dormir sur le côté homolatéral","Paresthésies des trois premiers doigts"],"r":[0,1,2,3,4],"e":"Les cinq signes sont cités dans la fiche.","s":4},{"q":"Quelle conduite s'applique à une lésion SLAP de type II ?","o":["Une chirurgie si le conservateur échoue","Un traitement conservateur exclusif, à vie","Une chirurgie d'emblée, sans essai conservateur","Une abstention, avec simple surveillance"],"r":0,"e":"Type I : conservateur. Type II : chirurgie envisagée en cas d'échec du conservateur. Type III : chirurgie.","s":4},{"q":"Quelles populations sont exposées au syndrome du canal carpien ?","o":["Tâches ménagères, à 40-60 ans","Travail prolongé sur ordinateur","Grossesse, en fin de terme","Diabète, polyarthrite, goutte","Course à pied intensive"],"r":[0,1,2,3],"e":"Toutes ces situations sont citées comme facteurs associés. L'arthrose est aussi un terrain favorisant.","s":4},{"q":"Quelles interventions sont proposées dans le syndrome fémoro-patellaire ?","o":["Activité modifiée","Immobilisation sélective","Force et flexibilité","Orthèses adaptées","Acromioplastie"],"r":[0,1,2,3],"e":"Modification de l'activité, immobilisation sélective, travail sélectif de force et de flexibilité, et orthèses. Le mouvement est aussi rééduqué.","s":4},{"q":"Quel est l'objectif du traitement conservateur, habituellement de premier choix, dans le conflit fémoro-acétabulaire ?","o":["Réduire l'inflammation, rééduquer les muscles, gagner en mobilité et en fonction","Immobiliser la hanche pendant six semaines, en extension et en abduction","Préparer systématiquement le patient à une arthroscopie de la hanche","Limiter définitivement les amplitudes de hanche, pour éviter le conflit"],"r":0,"e":"Le conservateur vise à réduire l'inflammation (PEACE & LOVE), rééduquer les schémas musculaires par l'exercice, améliorer la mobilité et restaurer la fonction (marche, escaliers, conduite, activité physique).","s":4},{"q":"Quelle cellule est responsable de la résorption osseuse ?","o":["L'ostéoclaste","L'ostéoblaste","Le chondrocyte","Le fibroblaste"],"r":0,"e":"Les ostéoclastes assurent la résorption ; les ostéoblastes synthétisent le collagène et contribuent à la minéralisation.","s":5},{"q":"Quelle est la proportion de collagène dans la matrice osseuse ?","o":["90 %","50 %","20 %","10 %"],"r":0,"e":"La matrice contient 90 % de collagène, avec prédominance du type I.","s":5},{"q":"De quelle vitamine dépend l'ostéocalcine ?","o":["La vitamine D","La vitamine K","La vitamine C","La vitamine B12"],"r":0,"e":"L'ostéocalcine est dépendante de la vitamine D ; l'acide γ-carboxyglutamique nécessite la vitamine K.","s":5},{"q":"Quelle vitamine est nécessaire à la synthèse de l'acide γ-carboxyglutamique ?","o":["La vitamine K","La vitamine D","La vitamine A","La vitamine E"],"r":0,"e":"Cet acide, fixateur du calcium, nécessite la vitamine K pour être synthétisé.","s":5},{"q":"Quel processus osseux perdure tout au long de la vie ?","o":["Le remodelage","La croissance","Le modelage","L'ossification"],"r":0,"e":"Croissance et modelage cessent à la fermeture du cartilage de conjugaison ; remodelage et réparation perdurent toute la vie.","s":5},{"q":"Que définit le remodelage osseux ?","o":["L'adaptation de la masse et de la forme de l'os aux contraintes","L'augmentation de la masse osseuse pendant la croissance","La seule modification de la forme de l'os, sans changer sa masse","La minéralisation initiale de l'os, pendant la vie fœtale"],"r":0,"e":"C'est l'adaptation de la masse et de la géométrie aux exigences fonctionnelles et mécaniques.","s":5},{"q":"Quelle fracture est typique de l'enfant ?","o":["La fracture en bois vert","La fracture du col du fémur","La fracture de la clavicule chez l'adulte","La fracture pathologique sur ostéoporose"],"r":0,"e":"Chez l'enfant : extrémité distale du radius et fracture en bois vert (incomplète).","s":5},{"q":"Quelle fracture est la plus caractéristique de la personne âgée ?","o":["Le col du fémur","La clavicule","Le tibia distal","La rotule"],"r":0,"e":"Chez l'adulte : clavicule, radius distal, poignet, col du fémur (personnes âgées +++) et tibia.","s":5},{"q":"Quelle classification est utilisée pour les fractures de l'enfant touchant le cartilage de croissance ?","o":["Salter-Harris","BAMIC","Salter-Cobb","Outerbridge"],"r":0,"e":"La classification de Salter-Harris est celle citée dans le cours.","s":5},{"q":"Quelle est la durée de la phase inflammatoire de la consolidation osseuse ?","o":["1 à 2 semaines","1 à 2 jours","6 semaines","3 mois"],"r":0,"e":"La phase inflammatoire dure 1 à 2 semaines et représente 10 % du processus, avec fonction totalement restreinte.","s":5},{"q":"Quelle activité cellulaire domine la phase inflammatoire de la consolidation ?","o":["L'activité ostéoclastique","L'activité ostéoblastique","L'activité chondroblastique","L'activité fibroblastique exclusivement"],"r":0,"e":"Réaction inflammatoire, hématome, débridement de l'os et activité ostéoclastique.","s":5},{"q":"Quel pourcentage du processus de consolidation représente le remodelage ?","o":["50 %","10 %","20 %","30 %"],"r":0,"e":"Inflammatoire 10 %, cal mou 20 %, cal dur 20 %, remodelage 50 %.","s":5},{"q":"À quelle étape la ligne de fracture disparaît-elle complètement ?","o":["Au remodelage","Au cal mou","À la phase inflammatoire","Dès la première semaine"],"r":0,"e":"Au cal dur la ligne commence à disparaître ; elle disparaît au remodelage, avec formation d'os lamellaire.","s":5},{"q":"Quel est le délai de consolidation d'une fracture du 1/3 distal du tibia ?","o":["16 à 20 semaines","6 semaines","8 à 12 semaines","2 semaines"],"r":0,"e":"1/3 distal du tibia : union 8-10 semaines, consolidation 16-20 semaines.","s":5},{"q":"Quel est le délai d'union d'une fracture du 1/3 proximal de l'humérus ?","o":["3 semaines","6 semaines","12 semaines","1 semaine"],"r":0,"e":"1/3 proximal de l'humérus : union à 3 semaines, consolidation à 6 semaines.","s":5},{"q":"Quelle méthode d'immobilisation non chirurgicale est la plus fréquente ?","o":["L'immobilisation plâtrée","La fixation externe","La traction","La fixation interne"],"r":0,"e":"Le plâtre (ou fibre de verre) est la méthode non chirurgicale la plus fréquente.","s":5},{"q":"Quel risque est spécifiquement associé à la fixation externe ?","o":["L'ostéomyélite et l'infection des vis","La myosite ossifiante du muscle voisin","La luxation de l'articulation voisine","La thrombose de l'artère principale du membre"],"r":0,"e":"La fixation externe expose au risque d'ostéomyélite et d'infection des vis, mais permet une meilleure gestion quand la peau est très endommagée.","s":5},{"q":"Quel principe s'applique au renforcement musculaire avant le remodelage osseux ?","o":["Ni charges élevées ni longs bras de levier","Des charges maximales, systématiquement","Aucune mobilisation des segments voisins","Aucune contraction musculaire du membre"],"r":0,"e":"Il faut proscrire les charges élevées et les longs bras de levier avant que l'os ne soit remodelé.","s":5},{"q":"Quelle complication ne figure PAS parmi celles des fractures ?","o":["La capsulite rétractile gléno-humérale","Le cal vicieux, avec une déformation","La non-union, ou pseudarthrose","La myosite ossifiante, au muscle voisin"],"r":0,"e":"Les complications citées sont : retard d'union, non-union, cal vicieux, dysmétries, raideur, nécrose, problèmes autonomiques et myosite ossifiante.","s":5},{"q":"De quoi est composé le cartilage articulaire ?","o":["De chondrocytes et d'une matrice de protéoglycanes, collagène et eau","D'ostéoblastes et de sels minéraux, comme l'os sous-chondral","De fibroblastes et d'élastine, comme le tissu conjonctif lâche","De myofibroblastes et de collagène de type III, comme la cicatrice"],"r":0,"e":"Cellules (chondrocytes) + matrice extracellulaire faite de protéoglycanes, collagène et eau.","s":5},{"q":"Pourquoi la réparation du cartilage est-elle très limitée ?","o":["Pas de vaisseaux et une réponse cellulaire limitée","Un excès de vascularisation, qui gêne la cicatrisation","Une prolifération cellulaire trop rapide et désorganisée","Une absence totale de matrice extracellulaire"],"r":0,"e":"Ce sont les deux obstacles majeurs cités dans le cours.","s":5},{"q":"Qu'est-ce qui distingue une lésion cartilagineuse profonde ?","o":["Elle atteint l'os sous-chondral et ses vaisseaux","Elle guérit toujours, sans aucune séquelle","Elle ne concerne que les chondroblastes de surface","Elle reste toujours asymptomatique, même à l'effort"],"r":0,"e":"L'accès au réseau vasculaire osseux permet la présence des 3 phases de réponse à la lésion tissulaire.","s":5},{"q":"Quelle affirmation sur l'arthrose est correcte ?","o":["Un processus dégénératif non inflammatoire des articulations portantes","Une maladie auto-immune inflammatoire, avec des anticorps circulants","Une atteinte surtout des petites articulations des mains et des pieds","Une progression toujours brutale, en quelques semaines seulement"],"r":0,"e":"L'arthrose découle d'un processus dégénératif non inflammatoire affectant essentiellement les articulations portantes.","s":5},{"q":"Comment évolue la douleur arthrosique ?","o":["Elle diminue avec le repos et s'aggrave avec la charge","Elle s'aggrave au repos et cède à l'effort","Elle est permanente et indépendante de l'activité","Elle est exclusivement nocturne"],"r":0,"e":"Douleur qui diminue avec le repos, s'aggrave avec la charge, intense au réveil avec tendance à diminuer.","s":5},{"q":"Quelles amplitudes sont typiquement perdues dans la coxarthrose ?","o":["Flexion, abduction et rotation interne","Extension et rotation externe seulement","Toutes les amplitudes, de façon égale","Aucune amplitude, seule la douleur compte"],"r":0,"e":"La coxarthrose limite la flexion, l'abduction et la rotation interne, avec une douleur irradiant de l'aine vers la cuisse.","s":5},{"q":"Quelle est la durée de vie moyenne d'une prothèse de genou ?","o":["15 à 20 ans","20 à 25 ans","10 ans","5 ans"],"r":0,"e":"Hanche 20-25 ans, genou 15-20 ans, épaule inversée environ 10 ans.","s":5},{"q":"Quand introduit-on la charge après une prothèse de hanche non cimentée ?","o":["Entre 6 et 12 semaines","Dès le 1ᵉʳ jour post-opératoire","À 6 mois","Jamais"],"r":0,"e":"Cimentée : charge dès le 1ᵉʳ jour. Non cimentée : 6 à 12 semaines.","s":5},{"q":"Quelles positions sont luxantes après une PTH par voie postérolatérale ?","o":["Flexion au-delà de 90°, adduction et rotation interne","Hyperextension au-delà de 10°, adduction et rotation externe","Abduction au-delà de 45° et rotation externe","Extension complète à 0° et abduction"],"r":0,"e":"Postérolatérale : flexion > 90°, adduction, rotation interne. Antérolatérale et latérale : hyperextension, rotation externe, adduction.","s":5},{"q":"À quel délai débute la mobilisation passive continue (CPM) après une prothèse de genou ?","o":["À 48 h","À 2 semaines","À 6 semaines","Immédiatement en salle de réveil"],"r":0,"e":"La CPM est débutée à 48 h, le patient étant positionné en décubitus dorsal, membre surélevé et en extension.","s":5},{"q":"Quel est le pronostic attendu en flexion active après une prothèse de genou ?","o":["100°","60°","140°","30°"],"r":0,"e":"Pronostic : extension complète, 100° de flexion active, appui en charge totale, stabilité et autonomie dans les AVQ.","s":5},{"q":"Quelles sont les fonctions des ostéoblastes ?","o":["Synthétiser le collagène","Contribuer à la minéralisation","Médier la résorption des ostéoclastes","Synthétiser des facteurs de croissance","Résorber directement la matrice osseuse"],"r":[0,1,2,3],"e":"L'ostéoblaste synthétise le collagène, minéralise, médie la résorption ostéoclastique et produit des facteurs de croissance. C'est l'ostéoclaste qui résorbe.","s":5},{"q":"Quels facteurs régulent le remodelage osseux ?","o":["Génétiques","Mécaniques","Vasculaires","Nutritionnels","Hormonaux","Immunologiques"],"r":[0,1,2,3,4],"e":"Cinq familles de facteurs : génétiques, mécaniques, vasculaires, nutritionnels et hormonaux.","s":5},{"q":"Quelle est la différence entre croissance et modelage osseux ?","o":["La croissance augmente la masse, le modelage change la forme","La croissance change la forme, le modelage augmente la masse","Les deux perdurent toute la vie, comme le remodelage","Le modelage ne concerne que l'os cortical, pas le spongieux"],"r":0,"e":"Croissance = augmentation de la masse osseuse ; modelage = modification de la forme. Tous deux cessent à la fermeture du cartilage de conjugaison, contrairement au remodelage et à la réparation.","s":5},{"q":"Quelles causes de fracture s'ajoutent au traumatisme direct ou indirect ?","o":["Une pathologie : ostéoporose, troubles métaboliques, tumeur","Le stress ou la fatigue, par des charges répétées","L'avulsion, par arrachement d'un fragment osseux","Une carence isolée en vitamine C, chez l'adulte"],"r":[0,1,2],"e":"Pathologie associée, stress/fatigue et avulsion complètent les mécanismes traumatiques directs et indirects.","s":5},{"q":"Pourquoi l'incidence des fractures augmente-t-elle chez la femme après la ménopause ?","o":["La densité osseuse baisse nettement","L'activité des ostéoblastes augmente","Un excès de vitamine D fragilise l'os","Le cartilage de conjugaison se ferme"],"r":0,"e":"La chute de densité osseuse post-ménopausique (ostéoporose) explique la plus grande incidence de fractures chez la femme. Cette baisse de densité correspond à l'ostéoporose.","s":5},{"q":"Quels signes et symptômes évoquent une fracture ?","o":["Douleur intense augmentant avec le mouvement","Œdème marqué et déformation du contour","Position anormale du segment","Sensation de crépitation","Paresthésies distales isolées"],"r":[0,1,2,3],"e":"Douleur augmentée au mouvement, œdème, déformation, perte de fonction, position anormale et crépitation.","s":5},{"q":"Quelle est la fonction du segment pendant la phase de cal dur ?","o":["Initiée","Totalement restreinte","Restreinte","Presque normale à normale"],"r":0,"e":"Inflammatoire : fonction totalement restreinte. Cal mou : restreinte. Cal dur : initiée. Remodelage : presque normale à normale.","s":5},{"q":"Qu'est-ce qui caractérise la phase de cal mou ?","o":["Les ostéoblastes produisent du tissu fibreux, du cartilage et un peu d'os","Les ostéoclastes résorbent les extrémités, dans un hématome organisé","De l'os réticulé immature se forme, puis commence à se minéraliser","De l'os lamellaire remplace le cal, et l'excès de cal est résorbé"],"r":0,"e":"Le cal mou (20 %) est marqué par l'activité ostéoblastique : tissu fibreux, cartilage et un peu d'os.","s":5},{"q":"Quel est le délai de consolidation d'une fracture du 1/3 distal du radius ou du cubitus ?","o":["12 semaines","6 semaines","8 à 12 semaines","16 à 20 semaines"],"r":0,"e":"Union à 6 semaines, consolidation à 12 semaines pour le 1/3 distal du radius/cubitus.","s":5},{"q":"Quels sont les avantages et inconvénients de la fixation interne ?","o":["Elle permet une mobilisation précoce générale et spécifique","Elle inflige un traumatisme additionnel aux structures adjacentes","Elle expose à des complications chirurgicales et à l'infection","Elle est préférable quand la peau est très endommagée"],"r":[0,1,2],"e":"La fixation interne autorise la mobilisation précoce mais ajoute un traumatisme et des risques infectieux. C'est la fixation externe qui est préférée quand la peau est très abîmée.","s":5},{"q":"Pourquoi faut-il limiter le mouvement au niveau du trait de fracture ?","o":["Il peut léser davantage l'os, les vaisseaux, les nerfs et les tissus mous","Il accélère la résorption ostéoclastique au niveau du foyer de fracture","Il empêche la formation de l'hématome initial, nécessaire à la réparation","Il augmente trop vite la minéralisation, avec un risque de cal hypertrophique"],"r":0,"e":"Le mouvement au foyer peut léser davantage l'os et les structures voisines : vaisseaux sanguins, nerfs et tissus mous.","s":5},{"q":"Quelles conséquences l'immobilisation et le non-usage entraînent-ils pour le patient fracturé ?","o":["Amplitudes réduites par rétraction","Force diminuée","Altérations sensori-motrices","Fonction cardio-respiratoire altérée","Densité osseuse augmentée"],"r":[0,1,2,3],"e":"Perte d'amplitude, de force, altérations sensori-motrices, retentissement cardio-respiratoire, vasculaire et cutané, et baisse de la capacité fonctionnelle.","s":5},{"q":"Quels principes guident l'intervention après une fracture ?","o":["Mobiliser les segments non atteints","Respecter les délais du cal osseux","Surveiller la marche, sans surcharger","Éviter charges et leviers longs au début","Renforcer au maximum d'emblée"],"r":[0,1,2,3],"e":"Mobiliser ce qui peut l'être, respecter les délais du cal, adapter la marche et proscrire charges élevées et longs bras de levier avant le remodelage osseux.","s":5},{"q":"Quelles cellules assurent la réparation d'une lésion cartilagineuse superficielle ?","o":["Les chondroblastes, à la prolifération limitée","Les ostéoclastes, qui résorbent l'os sous-chondral","Les fibroblastes du périoste, qui produisent du collagène","Les cellules souches de la moelle osseuse, qui migrent"],"r":0,"e":"La lésion superficielle dépend exclusivement des chondroblastes, dont la prolifération est limitée — d'où une réparation très pauvre.","s":5},{"q":"Que se passe-t-il lors d'une lésion cartilagineuse profonde ?","o":["Des cellules indifférenciées deviennent chondrocytes et refont une matrice","Le cartilage se régénère à l'identique, sans aucune différence de structure","Aucune réponse cellulaire n'est possible, même avec l'accès aux vaisseaux","Seuls les ostéoclastes interviennent, en résorbant l'os sous la lésion"],"r":0,"e":"L'atteinte de l'os sous-chondral ouvre l'accès au réseau vasculaire : des cellules indifférenciées migrent et se différencient en chondrocytes. Mais le tissu de substitution n'est jamais identique à l'original.","s":5},{"q":"Quels facteurs prédisposent à l'arthrose ?","o":["Dysplasie de hanche","Surfaces irrégulières","Mauvais alignement","Obésité","Exercice avec impact","Calcium en excès"],"r":[0,1,2,3,4],"e":"Tous ces facteurs sont cités, avec la sénescence articulaire et les altérations pathologiques articulaires. Les surfaces irrégulières font suite à un traumatisme ; l'alignement concerne le membre inférieur.","s":5},{"q":"Pourquoi l'arthrose peut-elle rester longtemps asymptomatique ?","o":["Les symptômes n'apparaissent que quand l'os et la capsule sont atteints","Le cartilage est très innervé et masque la douleur par adaptation","La douleur est masquée par l'inflammation intense de la synoviale","Le diagnostic est purement radiologique, sans aucun symptôme possible"],"r":0,"e":"Jusqu'à un certain degré l'arthrose est asymptomatique : les symptômes surviennent quand l'os et la capsule sont touchés. Le début est insidieux et l'évolution lente.","s":5},{"q":"Quels éléments composent le traitement conservateur de l'arthrose ?","o":["Médication","Viscosupplémentation","Kinésithérapie","Perte de poids","Arthrodèse"],"r":[0,1,2,3],"e":"Le conservateur vise à diminuer douleur et raideur. Arthrodèse, ostéotomie et arthroplastie relèvent du chirurgical. Le traitement comprend aussi le PRP, l'exercice, l'éducation et les aides techniques.","s":5},{"q":"Quelles positions faut-il éviter après une PTH par voie antérolatérale ou latérale ?","o":["Hyperextension","Rotation externe","Adduction","Flexion à plus de 90°"],"r":[0,1,2],"e":"Voie antérolatérale et latérale : éviter hyperextension, rotation externe et adduction. La flexion au-delà de 90° concerne la voie postérolatérale.","s":5},{"q":"D'où vient la dénomination « inversée » de la prothèse d'épaule ?","o":["La concavité se situe au niveau de la glène","La tête humérale est remplacée par une tige droite","L'implant est posé par voie postérieure","La rotation de l'épaule est inversée"],"r":0,"e":"Dans la prothèse inversée, la concavité se trouve au niveau de la glène — d'où le nom. Elle est indiquée en cas de fracture complexe, de coiffe irréparable ou de dégénérescence avancée.","s":5},{"q":"Quelle caractéristique appartient à la dysfonction vertébrale mécanique ?","o":["Des plaintes aggravées par l'effort, soulagées par le repos","Une douleur soulagée par le mouvement et aggravée au repos","Une raideur matinale prolongée, de plus d'une heure","Une atteinte systémique constante, avec fièvre"],"r":0,"e":"La dysfonction mécanique s'aggrave à l'effort, se soulage au repos, avec une raideur de courte durée et sans atteinte systémique.","s":6},{"q":"Quelle caractéristique oriente vers une dysfonction inflammatoire ?","o":["Une douleur qui réveille la nuit, soulagée par le mouvement","Une douleur soulagée par le repos, aggravée par l'effort","Une raideur matinale de courte durée, moins de 15 minutes","Des radiographies toujours normales, même après des années"],"r":0,"e":"L'inflammatoire réveille le patient la nuit, est soulagée par le mouvement, avec une raideur matinale prolongée et une atteinte systémique.","s":6},{"q":"Quel signe évoque une dysfonction maligne ou infectieuse ?","o":["Pas de rythme défini, aucun facteur de soulagement","Un soulagement complet au repos, en position allongée","Une aggravation uniquement à l'effort, en fin de journée","Une raideur matinale de 5 minutes, qui cède vite"],"r":0,"e":"Douleur permanente très invalidante, sans rythme ni facteur de soulagement, faible réponse à la pharmacothérapie, asthénie, amaigrissement, fièvre.","s":6},{"q":"Quel élément est un red flag de fracture ?","o":["L'usage prolongé de corticoïdes","La kinésiophobie","Le manque de soutien social","La satisfaction au travail"],"r":0,"e":"Red flags de fracture : traumatisme et usage prolongé de corticoïdes.","s":6},{"q":"Quel élément est un red flag de malignité ?","o":["Une perte de poids soudaine","De la fièvre","Un traumatisme récent","Des croyances de kinésiophobie"],"r":0,"e":"Malignité : antécédents de maladie oncologique et perte de poids soudaine. La fièvre oriente vers l'infection.","s":6},{"q":"Lequel de ces éléments est un yellow flag ?","o":["Des croyances qui mènent à la kinésiophobie","Une fièvre inexpliquée, depuis plusieurs jours","Un antécédent personnel de cancer","Un traumatisme violent et récent"],"r":0,"e":"Yellow flags : kinésiophobie, manque de soutien social, traitements non conformes aux meilleures pratiques.","s":6},{"q":"Comment définit-on un syndrome radiculaire ?","o":["Une compression ou une inflammation des racines nerveuses","Une inflammation de la capsule des articulations postérieures","Une dégénérescence du seul corps vertébral, sans atteinte nerveuse","Une contracture des muscles paravertébraux, sans atteinte nerveuse"],"r":0,"e":"C'est la compression ou l'inflammation des racines nerveuses.","s":6},{"q":"Quel type de douleur caractérise le syndrome radiculaire ?","o":["Profonde, bien localisée, irradiée le long du dermatome","Superficielle, mal systématisée, sans trajet précis","Exclusivement au repos, jamais au mouvement","Bilatérale et symétrique, aux deux membres"],"r":0,"e":"Douleur profonde, bien localisée, irradiée le long du dermatome, avec sensation de brûlure et paresthésies.","s":6},{"q":"Quelle cause peut provoquer une compression directe d'une racine nerveuse ?","o":["Une ostéophytose de l'articulation interapophysaire postérieure","Une contracture musculaire simple, après un effort","Un déficit en vitamine D, avec ostéomalacie","Une bursite trochantérienne, sur la face externe de la hanche"],"r":0,"e":"Compression ou traction directe : dégénérescence ou rupture discale, ostéophytose de l'AIP.","s":6},{"q":"Depuis combien de temps une cervicalgie non spécifique doit-elle évoluer pour être retenue ?","o":["Au moins 1 jour","Au moins 3 mois","Au moins 12 semaines","Au moins 1 an"],"r":0,"e":"Le cours définit la cervicalgie non spécifique comme évoluant depuis au moins 1 jour, avec impact sur les AVQ.","s":6},{"q":"L'atteinte dans la cervico-brachialgie est le plus souvent :","o":["Mono-radiculaire","Pluri-radiculaire","Médullaire","Purement musculaire"],"r":0,"e":"L'atteinte est fréquemment mono-radiculaire, souvent liée à un processus dégénératif cervical.","s":6},{"q":"Quel facteur extrinsèque est associé à la cervicalgie ?","o":["La satisfaction au travail","La densité osseuse","La longueur des membres inférieurs","Le groupe sanguin"],"r":0,"e":"Facteurs extrinsèques cités : soutien social, satisfaction au travail, niveaux de stress, dépression.","s":6},{"q":"Quelle relation faut-il évaluer en cas de cervicalgie ?","o":["La relation cervicales-ATM","La relation hanche-genou","La relation épaule-coude","La relation lombaires-SI"],"r":0,"e":"Le cours insiste sur le dépistage des red flags et l'évaluation des relations cervicales-ATM. ATM : articulation temporo-mandibulaire ; SI : sacro-iliaque.","s":6},{"q":"Quelle est l'étiologie la plus fréquente de la lombalgie ?","o":["Non spécifique","Le spondylolisthésis","La sténose du canal","L'arthrose articulaire"],"r":0,"e":"L'étiologie idiopathique/non spécifique est la première ; les autres sont des conditions cliniques associées. La lombalgie non spécifique est dite idiopathique.","s":6},{"q":"À partir de quelle durée une lombalgie est-elle considérée comme chronique ?","o":["Plus de 12 semaines","Plus de 3 semaines","Plus de 6 mois","Plus de 1 an"],"r":0,"e":"Au-delà de 12 semaines, la lombalgie devient chronique et constitue un problème majeur de santé publique.","s":6},{"q":"Quelle caractéristique distingue l'irradiation de la lombalgie simple ?","o":["Des territoires flous, sans déficit sensitif ni moteur","Un trajet dermatomal précis, avec un déficit moteur","Des paresthésies constantes du pied, jour et nuit","Une abolition systématique des réflexes, des deux côtés"],"r":0,"e":"L'irradiation de la lombalgie se fait sur des territoires mal définis, sans altération sensitive, des réflexes ni de la force objective.","s":6},{"q":"Quel élément est un facteur de risque de chronicité de la lombalgie ?","o":["Le nombre et la fréquence des crises sur 12 mois","La taille du patient, au-delà de 1,90 m","La force du quadriceps, mesurée au dynamomètre","La densité minérale osseuse, mesurée à 50 ans"],"r":0,"e":"La quantité/fréquence des crises sur 12 mois est explicitement citée comme facteur de risque de chronicité.","s":6},{"q":"À quels niveaux se situent 90 à 95 % des conflits disco-radiculaires de la lombosciatalgie ?","o":["L5 et S1","L1 et L2","T12 et L1","S2 et S3"],"r":0,"e":"La lombosciatalgie est liée à des conflits disco-radiculaires L5-S1 dans 90 à 95 % des cas.","s":6},{"q":"Quel trajet suit la douleur de la lombosciatalgie ?","o":["Fesse, arrière de la cuisse, jambe et pied","Avant de la cuisse, jusqu'au genou seulement","Aine et face interne de la cuisse, jusqu'au genou","Région dorsale et thoracique, en ceinture"],"r":0,"e":"C'est le trajet décrit ; fréquemment la douleur ne présente pas le trajet complet. La face de cuisse est postérieure ou postéro-externe.","s":6},{"q":"La lombosciatalgie est-elle habituellement bilatérale ?","o":["Non, elle est très rarement bilatérale","Oui, presque toujours","Oui, dans 50 % des cas","Toujours bilatérale au stade chronique"],"r":0,"e":"Le cours précise qu'elle est très rarement bilatérale.","s":6},{"q":"Quelle différence sépare lombalgie et lombosciatalgie sur le plan neurologique ?","o":["La lombosciatalgie altère l'examen neurologique","La lombalgie simple abolit les réflexes du membre","Aucune différence sur le plan neurologique","La lombosciatalgie ne donne jamais de paresthésies"],"r":0,"e":"La lombosciatalgie s'accompagne d'altérations des réflexes, de la sensibilité et de la force ; la lombalgie non.","s":6},{"q":"Comment définit-on une scoliose structurale ?","o":["Une courbure de plus de 10° avec rotation des vertèbres","Toute déviation latérale du rachis, quelle que soit sa valeur","Une courbure qui se réduit complètement en flexion du tronc","Une cyphose thoracique supérieure à 40°, sans rotation"],"r":0,"e":"Scoliose structurale : courbure latérale > 10° accompagnée d'une rotation des corps vertébraux, avec tendance évolutive.","s":6},{"q":"Qu'est-ce qui caractérise l'attitude scoliotique ?","o":["Un rachis assez souple pour retrouver sa forme physiologique","Une rotation vertébrale fixée, visible en flexion du tronc","Une courbure toujours supérieure à 30°, à la radiographie","Une chirurgie systématique, dès le diagnostic posé"],"r":0,"e":"L'attitude scoliotique est réductible : le rachis retrouve sa forme physiologique.","s":6},{"q":"Quelle est la prévalence de la scoliose idiopathique chez les enfants de 10-16 ans ?","o":["2 à 4 %","10 à 15 %","0,1 %","20 %"],"r":0,"e":"Elle est présente chez 2 à 4 % des enfants de 10-16 ans, plus fréquente et plus grave chez les filles.","s":6},{"q":"Comment évoluent les courbures de moins de 30° arrivées à maturité osseuse ?","o":["Elles n'ont pas tendance à progresser","Elles progressent de 1° par an","Elles régressent spontanément","Elles nécessitent toujours une chirurgie"],"r":0,"e":"Les courbures ≤ 30° à maturité ne progressent pas ; celles ≥ 50° progressent de 1° par an.","s":6},{"q":"Quel outil mesure l'angle de la courbure du tronc ?","o":["Le scoliomètre","Le goniomètre","L'inclinomètre lombaire","Le dynamomètre"],"r":0,"e":"Le scoliomètre mesure l'angle de la courbure du tronc ; l'angle de Cobb se mesure sur radiographie.","s":6},{"q":"À partir de quelle courbure une orthèse est-elle indiquée ?","o":["≥ 25°","≥ 10°","≥ 40°","≥ 50°"],"r":0,"e":"Entre 20 et 29° : surveiller et mettre une orthèse pour les courbures ≥ 25°.","s":6},{"q":"À partir de quelle courbure la chirurgie est-elle indiquée ?","o":["≥ 40°","≥ 20°","≥ 30°","≥ 60°"],"r":0,"e":"À partir de 40°, il faut adresser pour chirurgie.","s":6},{"q":"Quel est l'effet réel des orthèses dans la scoliose ?","o":["Elles préviennent la progression, sans corriger la courbure","Elles corrigent définitivement la courbure, après deux ans de port","Elles n'ont aucun effet démontré sur la courbure ni sur sa progression","Elles remplacent la chirurgie dans tous les cas, même sévères"],"r":0,"e":"Les orthèses préviennent la progression de l'ordre de 60 à 74 % ; plus de 16 h/jour donne de meilleurs résultats. La progression est évitée dans 60 à 74 % des cas.","s":6},{"q":"Quel est le délai de retour à l'activité physique après correction chirurgicale d'une scoliose ?","o":["9 à 12 mois","2 semaines","4 à 5 jours","3 mois"],"r":0,"e":"Hospitalisation 4-5 jours, retour à l'école en 2 semaines, retour à l'activité physique en 9 à 12 mois en évitant les sports de contact.","s":6},{"q":"Quelles caractéristiques appartiennent à une dysfonction vertébrale mécanique ?","o":["Plaintes aggravées par l'effort et soulagées par le repos","Raideur matinale et post-repos de courte durée","Absence d'atteinte systémique","Radiographies normales ou avec altérations dégénératives","Soulagement par le mouvement après réveil nocturne"],"r":[0,1,2,3],"e":"La dysfonction mécanique s'aggrave à l'effort, se soulage au repos, donne une raideur brève, n'a pas d'atteinte systémique et montre des radiographies normales ou dégénératives. Le réveil nocturne soulagé par le mouvement est inflammatoire.","s":6},{"q":"Quels éléments évoquent une dysfonction vertébrale maligne ou infectieuse ?","o":["Pas de rythme, douleur permanente invalidante","Aucun facteur de soulagement","Faible réponse aux antalgiques usuels","Asthénie, amaigrissement, fièvre","Net soulagement par le repos"],"r":[0,1,2,3],"e":"Pas de rythme, douleur permanente, pas de soulagement, mauvaise réponse aux antalgiques et signes généraux. Le soulagement par le repos caractérise au contraire la douleur mécanique.","s":6},{"q":"Quel red flag oriente vers une infection ?","o":["Une fièvre et des antécédents de maladie infectieuse","Un usage prolongé de corticoïdes, sur plusieurs années","Une perte de poids soudaine, inexpliquée","Des antécédents de maladie oncologique"],"r":0,"e":"Fièvre et antécédents infectieux (VIH par exemple) sont les red flags d'infection. Les corticoïdes évoquent la fracture, la perte de poids et les antécédents oncologiques la malignité. Le VIH est un exemple d'antécédent infectieux.","s":6},{"q":"Quels sont les yellow flags identifiés par Oliveira et al. (2018) ?","o":["Croyances conduisant à la kinésiophobie","Manque de soutien social","Traitements non conformes aux meilleures pratiques","Antécédent de traumatisme récent"],"r":[0,1,2],"e":"Trois yellow flags : kinésiophobie, manque de soutien social et traitements non conformes aux meilleures pratiques. Le traumatisme est un red flag de fracture.","s":6},{"q":"Quels mécanismes peuvent produire un syndrome radiculaire ?","o":["Compression par le disque","Ostéophytes interapophysaires","Microtraumatismes répétés","Carence en vitamine D"],"r":[0,1,2],"e":"Compression/traction directe (disque, ostéophytose de l'AIP) et inflammation nerveuse liée aux microtraumatismes de l'agent compressif. Les microtraumatismes de l'agent compressif enflamment le nerf.","s":6},{"q":"Dans un syndrome radiculaire, les réflexes et la force sont :","o":["Parfois atteints, parfois non","Toujours abolis, du même côté","Toujours normaux, des deux côtés","Atteints seulement en cas de fièvre"],"r":0,"e":"La fiche précise que les réflexes et la force peuvent être ou non affectés dans le syndrome radiculaire.","s":6},{"q":"Quels symptômes composent le tableau de la cervico-brachialgie ?","o":["Douleur intense, surtout la nuit","Douleur accrue au mouvement du cou et du bras","Paresthésies du territoire atteint","Mobilité cervicale diminuée","Insomnies associées","Perte thermo-algique des jambes"],"r":[0,1,2,3,4],"e":"Les cinq symptômes sont cités.","s":6},{"q":"Quelles atteintes neurales peuvent accompagner une cervico-brachialgie ?","o":["Altérations sensitives","Perte de force","Altérations des réflexes myotendineux","Perte de l'odorat"],"r":[0,1,2],"e":"Altérations sensitives, perte de force et altérations des réflexes myotendineux sont les trois atteintes neurales possibles.","s":6},{"q":"Quelles interventions sont proposées dans la cervicalgie (Verhagen, 2021) ?","o":["Exercice actif adapté","Thérapie manuelle","Massage","Médicaments","Collier permanent"],"r":[0,1,2,3],"e":"Exercice, thérapie manuelle, massage, médicaments et chirurgie. L'immobilisation permanente n'est pas retenue. L'exercice associe hydrothérapie, flexibilité et force des stabilisateurs cervicaux.","s":6},{"q":"Quelles conditions cliniques peuvent être associées à une lombalgie ?","o":["Spondylolisthésis","Sténose du canal lombaire","Pathologie discale","Arthrose interapophysaire","Scoliose posturale"],"r":[0,1,2,3],"e":"Spondylolisthésis, sténose lombaire, pathologie discale et arthrose de l'AIP. La lombalgie reste toutefois le plus souvent idiopathique et non spécifique.","s":6},{"q":"Quels éléments composent le tableau clinique de la lombalgie ?","o":["Début progressif, sauf en situation de traumatisme","Kinésiophobie et postures antalgiques","Augmentation de la tension des muscles proximaux","Intensité très variable","Altération objective de la force et des réflexes"],"r":[0,1,2,3],"e":"Début progressif, kinésiophobie, tension musculaire proximale et intensité variable. L'absence d'altération sensitive, des réflexes et de la force objective distingue la lombalgie de la lombosciatalgie.","s":6},{"q":"Que dit l'épidémiologie de la lombalgie ?","o":["Chacun aura au moins une lombalgie, le plus souvent bénigne","Elle ne touche que les travailleurs manuels, après 40 ans","Elle est rare avant 50 ans, sauf chez les sportifs","Elle évolue presque toujours vers la chronicité, après un épisode"],"r":0,"e":"Les données épidémiologiques indiquent que chacun connaîtra au moins un épisode de lombalgie, d'évolution bénigne dans la majorité des cas.","s":6},{"q":"Quelles sont les étiologies de la lombosciatalgie ?","o":["Conflit disco-radiculaire","Sténose du canal","Arthrose interapophysaire","Spondylolisthésis","Scoliose idiopathique"],"r":[0,1,2,3],"e":"Conflit disco-radiculaire, sténose du canal, arthrose des AIP et spondylolisthésis.","s":6},{"q":"Quelles particularités cliniques caractérisent la lombosciatalgie ?","o":["Douleur nocturne qui cède mal au repos","Examen neurologique altéré","Marche altérée, avec claudication","Trajet souvent incomplet","Atteinte bilatérale habituelle"],"r":[0,1,2,3],"e":"Douleur nocturne mal soulagée, atteinte neurologique objective, claudication et trajet souvent incomplet. L'atteinte bilatérale est au contraire très rare.","s":6},{"q":"Quelles sont les causes secondaires de scoliose structurale ?","o":["Inégalité de longueur des membres inférieurs","Dysplasie de hanche","Ostéogenèse imparfaite","Posture maintenue au bureau"],"r":[0,1,2],"e":"Inégalité de longueur des membres, dysplasie de hanche et ostéogenèse imparfaite. La posture maintenue cause plutôt une attitude scoliotique, réductible.","s":6},{"q":"Chez qui la scoliose idiopathique est-elle plus fréquente et plus grave ?","o":["Chez les filles","Chez les garçons","Indifféremment selon le sexe","Chez les enfants de moins de 5 ans"],"r":0,"e":"La scoliose structurale idiopathique, d'origine génétique, est plus fréquente et plus grave chez les filles.","s":6},{"q":"Comment progressent les courbures de 50° ou plus arrivées à maturité osseuse ?","o":["D'environ 1° par an","Elles ne progressent plus","De 5° par an","De façon imprévisible et brutale"],"r":0,"e":"Les courbures ≥ 50° à la maturité progressent de l'ordre de 1° par an, contrairement à celles ≤ 30° qui n'ont pas tendance à évoluer.","s":6},{"q":"Quels outils permettent d'évaluer une scoliose ?","o":["Le test d'Adams","Le scoliomètre","L'angle de Cobb sur radiographie","Le squeeze test"],"r":[0,1,2],"e":"Test d'Adams, scoliomètre et angle de Cobb. Le squeeze test explore la syndesmose de la cheville.","s":6},{"q":"Pour une courbure de 22°, quelle est la conduite recommandée ?","o":["Surveiller, radiographie tous les 6 mois, adresser, orthèse à 25°","Opérer d'emblée, pour stabiliser la courbure de façon définitive","Poser une orthèse immédiatement, quelle que soit la valeur de l'angle","Ne rien surveiller, la courbure restant inférieure à 30°"],"r":0,"e":"Entre 20 et 29° : radiographie tous les 6 mois, adresser, surveiller, et poser une orthèse pour les courbures ≥ 25°.","s":6},{"q":"Quelles précisions sont exactes concernant le port d'orthèse dans la scoliose ?","o":["Plus de 16 h par jour","L'orthèse de Boston","Jusqu'à la chirurgie, si besoin","Une correction durable"],"r":[0,1,2],"e":"Plus de 16 h/jour, modèle Boston, jusqu'à l'indication chirurgicale. L'orthèse ne corrige pas la scoliose : elle en prévient la progression de 60 à 74 %.","s":6},{"q":"Où siège la lésion primitive de la polyarthrite rhumatoïde ?","o":["Au niveau de la membrane synoviale","Au niveau du cartilage articulaire","Au niveau de l'os sous-chondral","Au niveau du tendon"],"r":0,"e":"La lésion primitive est une synovite proliférative et destructrice de la membrane synoviale, évoluant par poussées.","s":7},{"q":"Quel est le profil articulaire typique de la polyarthrite rhumatoïde ?","o":["Une polyarthrite symétrique et destructrice des petites articulations","Une monoarthrite asymétrique des grosses articulations portantes","Une atteinte exclusive du rachis, avec une raideur lombaire matinale","Une arthrose des articulations portantes, sans aucune inflammation"],"r":0,"e":"PR = polyarthrite symétrique destructrice, petites articulations et synoviales (poignet, mains, pieds), avec effets systémiques.","s":7},{"q":"Quelle altération radiographique fait partie des critères de classification de la PR ?","o":["Ostéopénie et érosions","Ostéophytose marginale","Colonne en bambou","Pincement des articulations portantes"],"r":0,"e":"Les critères incluent les altérations radiographiques à type d'ostéopénie et d'érosions.","s":7},{"q":"Combien d'articulations au minimum doivent être atteintes selon les critères de classification de la PR ?","o":["3 ou plus","1","5 ou plus","10 ou plus"],"r":0,"e":"Arthrite de 3 articulations ou plus figure parmi les critères.","s":7},{"q":"Quel est le pic d'incidence du lupus érythémateux disséminé ?","o":["Entre 15 et 40 ans","Entre 50 et 65 ans","Après 70 ans","Avant 10 ans"],"r":0,"e":"Le lupus est prédominant chez la femme avec un pic d'incidence entre 15 et 40 ans.","s":7},{"q":"Quel facteur hormonal aggrave le lupus ?","o":["Les œstrogènes","La testostérone","La parathormone","Le cortisol"],"r":0,"e":"La présence d'œstrogènes aggrave la maladie.","s":7},{"q":"Quel pourcentage de patients lupiques présente des plaintes articulaires ?","o":["90 %","50 %","30 %","10 %"],"r":0,"e":"Les plaintes articulaires surviennent chez 90 % des personnes atteintes.","s":7},{"q":"Quel type de polyarthrite est le plus fréquent dans le lupus ?","o":["Une polyarthrite non érosive des petites articulations","Une polyarthrite érosive et destructrice des grosses articulations","Une monoarthrite du genou, avec épanchement abondant","Une arthrite des sacro-iliaques, avec raideur lombaire"],"r":0,"e":"Les plus fréquentes sont les polyarthrites non érosives des petites articulations des mains, pieds et poignets.","s":7},{"q":"Quelle éruption cutanée est caractéristique du lupus ?","o":["L'éruption en aile de papillon","Le psoriasis en plaques du coude","L'érythème noueux des deux jambes","Le purpura pétéchial des membres"],"r":0,"e":"L'éruption en aile de papillon et la photosensibilité sont caractéristiques.","s":7},{"q":"Quel cristal se dépose dans la goutte ?","o":["L'urate monosodique","Le pyrophosphate de calcium","L'hydroxyapatite","L'oxalate de calcium"],"r":0,"e":"La goutte résulte du dépôt de cristaux d'urate monosodique consécutif à une hyperuricémie.","s":7},{"q":"Au-delà de quelle concentration sérique d'acide urique le risque de goutte augmente-t-il ?","o":["7,0 mg/dl","3,0 mg/dl","12,0 mg/dl","1,0 mg/dl"],"r":0,"e":"Le risque augmente avec l'élévation de la concentration sérique d'acide urique au-dessus de 7,0 mg/dl.","s":7},{"q":"Comment débutent typiquement les premières crises de goutte ?","o":["Mono-articulaires, d'un début soudain la nuit","Polyarticulaires, symétriques d'emblée","Progressives, sur plusieurs mois","Post-traumatiques, après un choc local, toujours"],"r":0,"e":"Les premiers épisodes sont mono-articulaires avec un début soudain pendant la nuit ou au petit matin. Le début peut aussi survenir au petit matin.","s":7},{"q":"En combien de temps une crise de goutte se résout-elle spontanément ?","o":["3 à 10 jours","24 heures","4 à 6 semaines","3 mois"],"r":0,"e":"Résolution spontanée en 3 à 10 jours, avec desquamation cutanée locale.","s":7},{"q":"Quel médicament spécifique est cité dans le traitement de la goutte ?","o":["La colchicine","Le méthotrexate","L'insuline","Le paracétamol seul"],"r":0,"e":"Pharmacothérapie : anti-inflammatoires, colchicine, corticoïdes.","s":7},{"q":"Quel aliment faut-il éviter en cas de goutte ?","o":["Les fruits de mer et le gibier","Les produits laitiers frais et le fromage","Les légumes verts et les crudités","Le pain complet et les céréales"],"r":0,"e":"Il faut éviter les purines : viande de porc, alcool, gibier, fruits de mer. Ces aliments sont riches en purines.","s":7},{"q":"Quel marqueur génétique est associé à la spondylarthrite ankylosante ?","o":["HLA-B27","HLA-DR4","BRCA1","APOE4"],"r":0,"e":"Association au marqueur HLA-B27 dans 70 à 90 % des cas.","s":7},{"q":"Que signifie « séronégative » pour la spondylarthrite ankylosante ?","o":["Le liquide séreux ne contient pas de facteur rhumatoïde","Il n'y a aucune inflammation des articulations","Le HLA-B27 est absent chez la plupart des patients atteints","La vitesse de sédimentation reste toujours normale"],"r":0,"e":"Séronégative = absence de facteurs rhumatoïdes dans le liquide séreux.","s":7},{"q":"Quel est le sens de progression de la spondylarthrite ankylosante ?","o":["Ascendant, des sacro-iliaques vers les cervicales","Descendant, des cervicales vers les sacro-iliaques","Limité au rachis thoracique, sans extension","Aléatoire, d'un étage vertébral à l'autre, sans ordre"],"r":0,"e":"C'est une arthropathie inflammatoire chronique ascendante progressive. La maladie passe par les lombaires puis les dorsales.","s":7},{"q":"Que sont les syndesmophytes dans la spondylarthrite ankylosante ?","o":["Des ponts osseux, en colonne de bambou","Des érosions articulaires, aux marges","Des dépôts calciques, dans les tendons","Des nodules sous-cutanés, aux coudes"],"r":0,"e":"La formation de ponts osseux et de syndesmophytes donne l'aspect radiologique de colonne en bambou.","s":7},{"q":"Quelle posture est typique de la spondylarthrite ankylosante ?","o":["Cyphose thoracique augmentée, menton en protraction","Hyperlordose lombaire marquée, tête en arrière","Scoliose à double courbure, bassin basculé","Cyphose lombaire isolée, avec un rachis thoracique plat"],"r":0,"e":"Cyphose thoracique augmentée, protraction du menton, rectitude de la lordose lombaire et léger flexum des genoux et de la hanche. La lordose lombaire s'efface (rectitude) et un léger flexum de hanche et de genou s'installe.","s":7},{"q":"Quel est le pronostic vital de la spondylarthrite ankylosante ?","o":["Elle ne compromet pas l'espérance de vie","Elle réduit l'espérance de vie de 10 ans","Elle est rapidement fatale","Le pronostic est réservé"],"r":0,"e":"Malgré une incapacité progressive, la maladie ne compromet pas l'espérance de vie : bon pronostic.","s":7},{"q":"Combien de points douloureux au minimum sont requis pour le diagnostic de fibromyalgie ?","o":["11 sur 18","5 sur 12","18 sur 18","3 sur 10"],"r":0,"e":"Au moins 11 des 18 points douloureux à la pression digitale bilatérale, sans facteurs rhumatoïdes.","s":7},{"q":"Comment définit-on la fibromyalgie ?","o":["Une dysfonction autonome et neuro-endocrine","Une maladie auto-immune destructrice","Une arthropathie séronégative","Une pathologie dégénérative du cartilage"],"r":0,"e":"C'est une dysfonction autonome et neuro-endocrine, avec douleur diffuse chronique, troubles du sommeil et fatigue.","s":7},{"q":"Quel est l'effet de l'exercice dans la fibromyalgie ?","o":["Il améliore le tonus parasympathique et la douleur","Il aggrave systématiquement tous les symptômes","Il n'a aucun effet démontré, sur aucun symptôme","Il est contre-indiqué, en raison de la fatigue chronique"],"r":0,"e":"L'exercice améliore le tonus parasympathique, la perception de la douleur, la force, réduit les points douloureux et améliore dépression, anxiété et qualité de vie. Il réduit aussi le nombre de points douloureux.","s":7},{"q":"Quelle est la prévalence des fractures ostéoporotiques chez la femme post-ménopausée ?","o":["1 sur 3","1 sur 10","1 sur 20","1 sur 2"],"r":0,"e":"1 femme sur 3 en post-ménopause et 1 homme sur 5 après 65 ans subiront au moins 1 fracture ostéoporotique.","s":7},{"q":"Quel T-score définit l'ostéoporose ?","o":["Inférieur à −2,5","Entre −1 et −2,5","Supérieur à −1","Supérieur à 0"],"r":0,"e":"T-score > −1 : normal ; entre −1 et −2,5 : ostéopénie ; < −2,5 : ostéoporose.","s":7},{"q":"Quelles fractures caractérisent l'ostéoporose de type I ?","o":["Fractures de Colles et vertébrales","Fractures de hanche et d'humérus","Fractures du tibia","Fractures de la clavicule"],"r":0,"e":"Type I (post-ménopause, 50-65 ans) : fractures de Colles et vertébrales. Type II (après 65 ans) : hanche et humérus.","s":7},{"q":"Quels sites sont explorés par la DEXA ?","o":["Rachis lombaire, col du fémur, radius distal","Crâne, mandibule et vertèbres cervicales","Sternum, côtes et extrémité proximale de l'humérus","Calcanéus, tibia distal et os du tarse"],"r":0,"e":"Ce sont les trois sites de mesure cités dans le cours. Le rachis est mesuré de L1 à L4.","s":7},{"q":"Quel est l'effet de l'exercice physique dans l'ostéoporose ?","o":["Il stimule les ostéoblastes et prévient les chutes","Il stimule les ostéoclastes et accélère la résorption","Il est contre-indiqué, par risque de fracture","Il n'agit que sur la douleur, sans effet sur l'os"],"r":0,"e":"L'exercice stimule l'activité des ostéoblastes et contribue à la prévention des chutes.","s":7},{"q":"Quelle adaptation de l'exercice s'impose en cas de rétinopathie diabétique ?","o":["Éviter les pressions systoliques élevées et la tête basse","Privilégier les charges maximales, avec des efforts en apnée","Favoriser les activités à fort impact, comme les sauts","Interdire toute activité, par précaution"],"r":0,"e":"Il faut éviter les pressions systoliques élevées, l'entraînement de force à charges élevées, le fort impact, les efforts exténuants des membres supérieurs et les inclinaisons tête basse. La tête ne doit pas descendre sous la ceinture ; on évite aussi la force à charges élevées.","s":7},{"q":"Quels sont les principes généraux communs d'intervention dans les conditions rhumatologiques ?","o":["Traitement symptomatique","Capacité fonctionnelle maintenue","Éducation et conseil","Immobilisation prolongée"],"r":[0,1,2],"e":"Trois principes communs : symptomatique, capacité fonctionnelle, éducation et conseil. La capacité fonctionnelle est à augmenter ou à maintenir.","s":7},{"q":"Quel est le mode de début des plaintes selon la pathologie rhumatologique ?","o":["Polyarthrite : insidieux ou soudain","Goutte : soudain, souvent la nuit","Spondylarthrite : insidieux","Fibromyalgie : par crises","Lupus : toujours insidieux"],"r":[0,1,2,3],"e":"PR : insidieux ou soudain · lupus : soudain, par poussées · goutte : soudain · spondylarthrite : insidieux · fibromyalgie : par crises.","s":7},{"q":"Quelles articulations la polyarthrite rhumatoïde touche-t-elle préférentiellement ?","o":["Les poignets","Les mains","Les pieds","Les hanches"],"r":[0,1,2],"e":"La PR touche les petites articulations et synoviales : poignet, mains et pieds.","s":7},{"q":"Quels critères de classification de la polyarthrite rhumatoïde sont cités ?","o":["Raideur matinale","Arthrite symétrique","Nodules sous-cutanés","Facteurs rhumatoïdes sériques","Présence de HLA-B27"],"r":[0,1,2,3],"e":"Raideur matinale, arthrite d'au moins 3 articulations, arthrite des mains, arthrite symétrique, nodules sous-cutanés, facteurs rhumatoïdes et altérations radiographiques. HLA-B27 concerne la spondylarthrite.","s":7},{"q":"Quelle est l'étiologie de la polyarthrite rhumatoïde ?","o":["Multifactorielle, chez un sujet génétiquement susceptible","Strictement génétique, transmise de façon dominante","Strictement infectieuse, d'origine virale","Purement mécanique, par usure des articulations portantes"],"r":0,"e":"Étiologie multifactorielle : génétique et non génétique (environnementaux, endocriniens, infectieux), avec une réponse immunitaire persistante chez l'individu génétiquement susceptible. Elle associe facteurs génétiques et non génétiques, avec une réponse immunitaire persistante.","s":7},{"q":"Quels objectifs sont poursuivis dans la prise en charge de la polyarthrite rhumatoïde ?","o":["Survivre longtemps, avec une bonne qualité de vie","Éviter l'incapacité au quotidien","Vivre avec le moins de plaintes possible","Un traitement peu toxique et à coût raisonnable","Une rémission radiologique complète en trois mois"],"r":[0,1,2,3],"e":"Les quatre objectifs sont énoncés dans la fiche.","s":7},{"q":"Quels facteurs environnementaux sont impliqués dans le lupus ?","o":["Certains médicaments","Les rayons ultraviolets","Certains virus","Une carence en fer"],"r":[0,1,2],"e":"Médicaments, rayonnement UV et virus sont les facteurs environnementaux cités, aux côtés des facteurs immunologiques, génétiques et hormonaux.","s":7},{"q":"Quel est le pronostic du lupus érythémateux disséminé ?","o":["Des poussées de gravité variable, un pronostic réservé","Une guérison complète en quelques mois, sans rechute aucune","Une évolution linéaire, lente et prévisible","Un pronostic excellent, même sans traitement"],"r":0,"e":"Poussées successives de gravité variable, diagnostic difficile et pronostic réservé. Le diagnostic est en outre difficile.","s":7},{"q":"Quelles articulations la goutte peut-elle atteindre, au-delà des orteils ?","o":["Les doigts","La tibio-tarsienne","Le poignet","Le coude et le genou","Les sacro-iliaques"],"r":[0,1,2,3],"e":"Orteils et doigts, tibio-tarsienne, poignet, coude et genou. Les sacro-iliaques sont le point de départ de la spondylarthrite ankylosante.","s":7},{"q":"Quels facteurs aggravent la goutte ?","o":["Une obésité","La consommation d'alcool","Une alimentation riche en purines","Le diabète et l'hypertension","L'excès d'exercice physique","Un régime pauvre en viande"],"r":[0,1,2,3,4],"e":"Tous ces facteurs sont cités comme aggravants, avec les drogues, sur un terrain héréditaire. La lithiase rénale et l'athérosclérose aggravent aussi la goutte.","s":7},{"q":"Comment évoluent les crises de goutte dans le temps ?","o":["Elles deviennent plus fréquentes et ne cèdent plus seules","Elles s'espacent peu à peu, jusqu'à disparaître","Elles gardent toujours le même profil, d'une crise à l'autre","Elles guérissent après le troisième épisode"],"r":0,"e":"Les crises suivantes sont plus fréquentes, plus longues à régresser et perdent leur résolution spontanée. La goutte ne guérit pas.","s":7},{"q":"Quels signes accompagnent une crise de goutte ?","o":["Douleur intense","Chaleur et rougeur","Œdème local","Fièvre modérée","Desquamation cutanée","Ankylose immédiate"],"r":[0,1,2,3,4],"e":"Les cinq éléments composent le tableau de la crise, qui se résout spontanément en 3 à 10 jours au début.","s":7},{"q":"Quelles structures sont atteintes dans la spondylarthrite ankylosante ?","o":["La synoviale, la capsule, les tendons","Les sacro-iliaques, qui fusionnent","La symphyse, les costo-vertébrales","Les disques seuls, sans autre structure"],"r":[0,1,2],"e":"Synoviale, capsule, ligaments et tendons, avec ponts osseux et syndesmophytes, fusion des sacro-iliaques et ankylose de la symphyse pubienne, des costo-vertébrales et de la manubrio-sternale. S'y ajoute une ostéoporose. Les ligaments et la manubrio-sternale sont aussi atteints.","s":7},{"q":"Quel est le pronostic évolutif de la spondylarthrite ankylosante ?","o":["Une incapacité progressive, sans perte d'espérance de vie","Une évolution rapide vers le décès, dans les dix ans suivants","Une guérison spontanée fréquente, à l'âge adulte","Aucune incapacité, à aucun stade de la maladie"],"r":0,"e":"Début insidieux, schéma cyclique, incapacité progressive, mais la maladie ne compromet pas l'espérance de vie : le pronostic est bon. Le début est insidieux et l'évolution cyclique.","s":7},{"q":"Quelles sont les composantes du diagnostic de fibromyalgie ?","o":["Des symptômes physiques et psychiques","Des points douloureux à la pression","L'absence de facteurs rhumatoïdes","La présence de syndesmophytes au rachis"],"r":[0,1,2],"e":"Symptomatologie physique, cognitive et émotionnelle, au moins 11/18 points douloureux, et absence de facteurs rhumatoïdes. Il en faut au moins 11 sur 18 ; la symptomatologie est physique, cognitive et émotionnelle.","s":7},{"q":"Quelles interventions sont proposées dans la fibromyalgie ?","o":["L'exercice adapté","La pharmacothérapie","L'éducation et le conseil","Le soutien psychologique","L'immobilisation locale"],"r":[0,1,2,3],"e":"Exercice, pharmacothérapie, éducation et soutien psychologique. L'immobilisation n'est pas indiquée. Antalgiques, myorelaxants et antidépresseurs.","s":7},{"q":"Comment l'ostéoporose est-elle habituellement découverte ?","o":["Par une densitométrie, ou par une fracture sur un choc minime","Par une douleur osseuse constante, diffuse et nocturne","Par un bilan sanguin inflammatoire perturbé, avec une VS élevée","Par une raideur matinale prolongée, de plus d'une heure"],"r":0,"e":"L'ostéoporose est asymptomatique : elle est détectée par densitométrie, ou révélée par des fractures pour traumatismes minimes voire spontanées, une déformation du rachis et une perte de taille. Elle est asymptomatique avant la fracture.","s":7},{"q":"Quel est le mécanisme de l'ostéoporose de type II ?","o":["Formation osseuse diminuée, absorption du calcium réduite","Production d'œstrogènes diminuée, après la ménopause","Mécanisme multifactoriel, chez le jeune adulte","Activité ostéoblastique excessive, avec un os anormalement dense"],"r":0,"e":"Type I (post-ménopause) : chute des œstrogènes. Type II (après 65 ans) : baisse de la formation osseuse, hyperparathyroïdie secondaire, malabsorption calcique. Type III (jeune adulte) : multifactoriel. S'y ajoute une hyperparathyroïdie secondaire.","s":7},{"q":"Quelles mesures composent l'intervention dans l'ostéoporose ?","o":["Une alimentation riche en calcium","Moins de caféine et d'alcool","Un exercice physique régulier","L'ajustement des médicaments","Un repos strict au lit"],"r":[0,1,2,3],"e":"Alimentation, limitation de la caféine et de l'alcool, exercice (qui stimule les ostéoblastes et prévient les chutes), traitement substitutif et ajustement médicamenteux. L'alimentation apporte aussi la vitamine D ; un traitement substitutif peut être proposé.","s":7},{"q":"Quelles adaptations de l'exercice s'imposent en cas d'artériopathie périphérique diabétique ?","o":["Des pauses ou une alternance d'activités","Natation, vélo, tapis, chaîne ouverte","Un soin attentif des pieds","La force à charges élevées, en apnée"],"r":[0,1,2],"e":"L'artériopathie impose des pauses ou une alternance d'activités et un soin des pieds, du fait de la claudication douloureuse. Les charges élevées sont à éviter dans la rétinopathie.","s":7},{"q":"Comment l'OMS définit-elle l'activité physique ?","o":["Tout mouvement du corps qui requiert une dépense d'énergie","Un mouvement planifié, structuré et répétitif","Une pratique sportive en compétition, encadrée","Une activité de loisir, en dehors du travail et des trajets"],"r":0,"e":"C'est la définition de l'OMS (2022) ; l'exercice physique en est une sous-catégorie. Le mouvement est produit par le système squelettique.","s":8},{"q":"Quels sont les quatre qualificatifs de l'exercice physique selon l'ACSM ?","o":["Planifié, structuré, répétitif et intentionnel","Intense, long, varié et ludique","Aérobie, anaérobie, statique et dynamique","Analytique, global, passif et actif"],"r":0,"e":"L'ACSM (2019) définit l'exercice comme planifié, structuré, répétitif et intentionnel.","s":8},{"q":"Quelles composantes constituent la condition physique liée à la santé ?","o":["Force, flexibilité, aérobie, composition corporelle","Coordination, agilité, vitesse, équilibre","Puissance, endurance, souplesse, détente verticale","Mobilité, stabilité, endurance, posture assise"],"r":0,"e":"L'exercice est orienté vers le maintien d'habiletés et de la condition physique liée à la santé : force, flexibilité, capacité aérobie et composition corporelle.","s":8},{"q":"Quelle modification à long terme découle de l'exercice physique ?","o":["Une hausse du volume du tissu contractile","Une baisse durable de l'apport sanguin au muscle","Une perte de coordination motrice","Une disparition des adaptations biochimiques"],"r":0,"e":"À long terme : taille/volume du tissu contractile, apport sanguin, coordination motrice et modifications biochimiques.","s":8},{"q":"Quel défi lié au patient est cité dans la prescription d'exercice ?","o":["L'adhésion, freinée par la douleur ou la peur","Le coût du matériel, souvent élevé","La disponibilité des salles, limitée","La durée des séances, souvent trop courte en cabinet"],"r":0,"e":"Les trois défis cités sont le raisonnement clinique, l'adhésion du patient (douleur, fatigue, kinésiophobie) et les guidelines. La fatigue et la kinésiophobie freinent aussi l'adhésion.","s":8},{"q":"Dans le modèle de gestion du patient, que vient-il juste après l'évaluation ?","o":["La hiérarchisation des problèmes","Le pronostic de récupération","L'intervention thérapeutique","L'examen subjectif et l'anamnèse complète"],"r":0,"e":"Examen → Évaluation → Hiérarchisation des problèmes → Diagnostic → Pronostic → Intervention, avec réévaluation constante.","s":8},{"q":"Quel élément du modèle de Hall & Brody est décrit comme « constant » ?","o":["La réévaluation","L'examen objectif","Le diagnostic","Le pronostic"],"r":0,"e":"La réévaluation est constante tout au long du processus.","s":8},{"q":"Quel principe décrit la perte des gains à l'arrêt de la stimulation ?","o":["La réversibilité","La spécificité","La surcharge","L'adaptation"],"r":0,"e":"La réversibilité traduit la perte des adaptations lorsque le stimulus cesse.","s":8},{"q":"Quel principe impose de dépasser le niveau habituel de sollicitation ?","o":["La surcharge","La progression","La régularité","L'individualisation"],"r":0,"e":"La surcharge est le principe qui déclenche l'adaptation.","s":8},{"q":"Quel principe justifie d'adapter la prescription aux objectifs propres de la personne ?","o":["L'individualisation","La spécificité","La variabilité","La progression"],"r":0,"e":"Le principe d'individualisation impose de ne pas oublier les objectifs de la personne elle-même.","s":8},{"q":"Que signifie l'acronyme FITT ?","o":["Fréquence, Intensité, Temps, Type","Force, Intensité, Tempo, Technique","Flexibilité, Instabilité, Tonus, Travail","Fonction, Impact, Tolérance, Terrain"],"r":0,"e":"FITT = Fréquence, Intensité, Temps (durée) et Type.","s":8},{"q":"Quelle variable ne fait PAS partie des variables complémentaires de prescription ?","o":["La température ambiante","Les séries","Les répétitions","L'intervalle de repos"],"r":0,"e":"Les variables complémentaires citées sont : séries, répétitions, intervalle de repos, continu ou alterné.","s":8},{"q":"Quel paramètre permet de faire progresser le degré de difficulté d'un exercice ?","o":["Le bras de levier","La couleur du matériel","L'horaire de la séance","Le nombre de thérapeutes"],"r":0,"e":"Progression par : pesanteur, bras de levier, charge, amplitudes de mouvement et vitesse.","s":8},{"q":"Combien de piliers compte l'exercice thérapeutique ?","o":["5","3","4","7"],"r":0,"e":"Mobilité, flexibilité, force musculaire, reprogrammation sensori-motrice et pliométrie.","s":8},{"q":"Sur quoi la mobilité a-t-elle des effets directs ?","o":["Sur la physiologie articulaire","Sur la fibre musculaire","Sur les récepteurs sensori-moteurs","Sur la puissance"],"r":0,"e":"La mobilité vise l'amplitude articulaire avec des effets directs sur la physiologie articulaire.","s":8},{"q":"Sur quoi la flexibilité a-t-elle des effets directs ?","o":["Sur la fibre musculaire","Sur la physiologie articulaire","Sur le système cardio-respiratoire","Sur la composition corporelle"],"r":0,"e":"Mobilité → physiologie articulaire ; flexibilité → fibre musculaire. C'est la distinction clé entre les deux piliers.","s":8},{"q":"Sur quoi la reprogrammation sensori-motrice a-t-elle des effets directs ?","o":["Sur les récepteurs sensori-moteurs","Sur la fibre musculaire striée","Sur le tissu osseux sous-chondral","Sur la capacité aérobie du patient"],"r":0,"e":"La RSM vise la qualité du mouvement, avec des effets directs sur les récepteurs sensori-moteurs.","s":8},{"q":"Que vise la pliométrie ?","o":["La puissance, l'agilité et la vitesse","L'amplitude articulaire, la souplesse","La composition corporelle, la masse grasse","La lubrification du cartilage"],"r":0,"e":"La pliométrie vise à maintenir ou améliorer la puissance, l'agilité et la vitesse.","s":8},{"q":"Quelle sensation doit induire un étirement ?","o":["Un inconfort, sans douleur","Une douleur vive, aiguë","Aucune sensation, ni gêne","Une brûlure intense, persistante"],"r":0,"e":"L'étirement doit induire un inconfort et non une douleur.","s":8},{"q":"Quelles conditions favorisent un travail de flexibilité efficace ?","o":["Patient détendu, postures confortables, chaleur","Patient contracté, en effort maximal","Environnement froid, pour éviter l'œdème","Postures asymétriques, pour solliciter davantage"],"r":0,"e":"Le patient doit être détendu, dans des postures équilibrées et confortables, avec des conditions de température adéquates. La température doit être adéquate et les postures équilibrées.","s":8},{"q":"Quels types d'étirements sont possibles ?","o":["Statiques, dynamiques, passifs ou actifs","Statiques seulement, toujours passifs","Passifs seulement, toujours assistés","Balistiques seulement, avec des rebonds rapides"],"r":0,"e":"Les exercices de flexibilité peuvent être statiques, dynamiques, passifs ou actifs.","s":8},{"q":"Quels sont les 3 moments d'une séance de travail de force ?","o":["Échauffement, force, retour au calme","Étirement, force, nouvel étirement","Évaluation, exercice, réévaluation finale","Mobilité, force, pliométrie"],"r":0,"e":"La séance contient toujours ces trois moments distincts.","s":8},{"q":"Quel modèle structure les étapes du travail de force ?","o":["Le modèle OPT du NASM","Le modèle FITT de l'ACSM","Le modèle de Hall et Brody","Le modèle PEACE & LOVE"],"r":0,"e":"Le modèle OPT (NASM, 2021) organise plusieurs étapes travaillant des caractéristiques différentes. Modèle OPT : NASM, 2021.","s":8},{"q":"Que doit-on introduire graduellement en reprogrammation sensori-motrice ?","o":["Des niveaux d'instabilité croissants","Des charges maximales, dès la première séance","Des amplitudes extrêmes, en fin de course","Des vitesses explosives, en sauts"],"r":0,"e":"On introduit graduellement différents niveaux d'instabilité, en fournissant une stimulation adaptée au système sensori-moteur.","s":8},{"q":"Sous quelles formes la RSM peut-elle être travaillée ?","o":["En statique, en dynamique, en fonctionnel","En dynamique seulement, sur sol instable","En charge seulement, debout sur un pied","En passif seulement, par le thérapeute"],"r":0,"e":"La RSM se travaille en statique, en dynamique et en fonctionnel.","s":8},{"q":"Quel mécanisme physiologique la pliométrie active-t-elle ?","o":["Le cycle étirement/raccourcissement","Le réflexe myotatique inverse seul","La sommation temporelle","La plasticité corticale"],"r":0,"e":"La pliométrie repose sur l'activation du cycle étirement/raccourcissement : pré-étirement puis contraction explosive.","s":8},{"q":"Quels sont les prérequis avant de débuter la pliométrie ?","o":["Pas d'œdème ni douleur, force et amplitude normales","Une force à 50 % du côté sain, mesurée au dynamomètre","Une amplitude encore limitée, mais devenue indolore au repos","Un œdème modéré, toléré s'il reste indolore"],"r":0,"e":"Le segment concerné doit être sans œdème ni douleur, avec amplitude articulaire, force et flexibilité normales. La flexibilité doit aussi être normale.","s":8},{"q":"Quels principes d'apprentissage moteur faut-il concilier ?","o":["La répétition et la variabilité de la tâche","La répétition seule, sans aucune variation","La variabilité seule, sans aucune répétition","La vitesse et la charge, à progresser ensemble"],"r":0,"e":"Il faut respecter les principes de l'apprentissage par la répétition mais aussi de l'adaptation par la variabilité de la tâche.","s":8},{"q":"Dans la gonarthrose, quels piliers sont travaillés à court terme (4-6 semaines) ?","o":["Mobilité, flexibilité, sensori-motricité","Force musculaire et pliométrie","Pliométrie seule, en charge","Force musculaire seule, en isométrique"],"r":0,"e":"Court terme : mobilité, flexibilité, RSM. Moyen terme : mobilité, FM, RSM. Long terme : FM, RSM, pliométrie. La sensori-motricité correspond à la RSM.","s":8},{"q":"À quel horizon la pliométrie est-elle introduite dans la prise en charge de la gonarthrose ?","o":["À long terme (12-24 semaines)","À court terme (4-6 semaines)","À moyen terme (6-12 semaines)","Dès la première séance"],"r":0,"e":"La pliométrie n'apparaît qu'à long terme, entre 12 et 24 semaines.","s":8},{"q":"Quelles activités entrent dans la définition de l'activité physique selon l'OMS ?","o":["Les loisirs","Les déplacements","Le travail","Les tâches ménagères","Le sport seul"],"r":[0,1,2,3],"e":"L'activité physique englobe tout mouvement corporel avec dépense d'énergie : loisirs, déplacements, travail, tâches domestiques — et l'exercice, qui n'en est qu'une sous-catégorie.","s":8},{"q":"Vers quoi l'exercice physique est-il orienté selon l'ACSM ?","o":["Le maintien d'habiletés motrices","La condition physique liée à la santé","La seule perte de poids, à court terme","La seule performance en compétition"],"r":[0,1],"e":"L'exercice vise le maintien d'habiletés (coordination, agilité, vitesse) et de la condition physique liée à la santé : force, flexibilité, capacité aérobie, composition corporelle. Ces habiletés sont la coordination, l'agilité et la vitesse.","s":8},{"q":"Quelles modifications cardio-respiratoires découlent de l'exercice physique ?","o":["Aérobie","Anaérobie","Fibres rapides et lentes","Tissus conjonctifs"],"r":[0,1,2],"e":"Les modifications cardio-respiratoires regroupent aérobie, anaérobie et contraction de fibres rapides et lentes. Composition corporelle et tissus conjonctifs relèvent des modifications induites par l'entraînement.","s":8},{"q":"Quels sont les trois défis identifiés pour le kinésithérapeute qui prescrit de l'exercice ?","o":["Le raisonnement clinique","L'adhésion du patient","Le niveau de preuve","Le coût du matériel"],"r":[0,1,2],"e":"Raisonnement clinique, adhésion du patient (douleur, fatigue, kinésiophobie) et travail au meilleur niveau de preuve disponible.","s":8},{"q":"Dans le modèle de Hall & Brody, quelles sont les deux composantes de l'examen ?","o":["Subjectif","Objectif","Radiologique","Biologique"],"r":[0,1],"e":"L'examen comporte un volet subjectif et un volet objectif, avant l'évaluation, la hiérarchisation, le diagnostic, le pronostic et l'intervention.","s":8},{"q":"Que recouvre l'étape d'évaluation dans le modèle de gestion du patient ?","o":["L'interprétation des données recueillies","La seule mesure de la douleur ressentie","La rédaction complète du compte rendu clinique","Le choix du matériel de rééducation"],"r":0,"e":"L'évaluation consiste à interpréter les données, dans le cadre de la CIF et du tableau physiopathologique. Elle se fait dans le cadre de la CIF et du tableau physiopathologique.","s":8},{"q":"Quel principe explique que les adaptations dépendent du type de stimulus appliqué ?","o":["La spécificité","La surcharge","La progression","L'adaptation"],"r":0,"e":"Le principe de spécificité : les adaptations obtenues sont spécifiques du stimulus appliqué.","s":8},{"q":"Quelles sont les deux notions complémentaires aux six principes de l'exercice ?","o":["La régularité","La variabilité","La rapidité","La symétrie"],"r":[0,1],"e":"Aux six principes (surcharge, spécificité, progression, réversibilité, adaptation, individualisation) s'ajoutent la régularité et la variabilité.","s":8},{"q":"Quels paramètres permettent de faire progresser le degré de difficulté d'un exercice ?","o":["La pesanteur","Le bras de levier","La charge externe","L'amplitude du geste","La vitesse d'exécution","L'heure de la séance"],"r":[0,1,2,3,4],"e":"Cinq leviers de progression : pesanteur, bras de levier, charge, amplitudes et vitesse.","s":8},{"q":"Quelle est la différence entre mobilité et flexibilité ?","o":["Mobilité sur l'articulation, flexibilité sur le muscle","Mobilité sur le muscle, flexibilité sur l'articulation","Les deux agissent sur le seul système neuromusculaire","Les deux visent la puissance, et non l'amplitude articulaire"],"r":0,"e":"Les deux visent l'amplitude articulaire, mais la mobilité a des effets directs sur la physiologie articulaire et la flexibilité sur la fibre musculaire. La mobilité agit sur la physiologie articulaire, la flexibilité sur la fibre musculaire.","s":8},{"q":"Quelles idées clés caractérisent le travail de mobilité ?","o":["Mouvement libre et de qualité","Amplitude de mouvement","Analytique et fonctionnel","Général et spécifique","Contraction explosive"],"r":[0,1,2,3],"e":"Mouvement libre, qualité du schéma, amplitude, analytique et fonctionnel, général et spécifique, et répétition. La contraction explosive relève de la pliométrie.","s":8},{"q":"Quelles conditions favorisent une séance de flexibilité efficace ?","o":["Patient détendu","Postures confortables","Température adéquate","Étirement douloureux"],"r":[0,1,2],"e":"Patient détendu, postures équilibrées et confortables, température adéquate. L'étirement doit induire un inconfort, jamais une douleur.","s":8},{"q":"Que précède obligatoirement le travail de force dans une séance ?","o":["L'échauffement","Le retour au calme","La pliométrie","L'évaluation radiographique"],"r":0,"e":"La séance de force comporte toujours trois moments : échauffement, travail de force adapté à l'objectif, puis retour au calme.","s":8},{"q":"Que faut-il réaliser avant d'engager un travail de force ?","o":["Une évaluation de la force","Une radiographie","Un test d'effort maximal","Une séance de pliométrie"],"r":0,"e":"L'évaluation de la force est un préalable, et le travail se structure ensuite en plusieurs étapes selon le modèle OPT (NASM, 2021).","s":8},{"q":"Quelles idées clés structurent la reprogrammation sensori-motrice ?","o":["Instabilité introduite peu à peu","Répétition contre variabilité","Qualité du mouvement contrôlée","Statique, dynamique, fonctionnel","Excentrique maximal, d'emblée"],"r":[0,1,2,3],"e":"Instabilité graduée, dialectique répétition/variabilité, contrôle de la qualité du mouvement, et déclinaison statique, dynamique et fonctionnelle.","s":8},{"q":"Sur quel mécanisme repose la pliométrie ?","o":["Un pré-étirement suivi d'une contraction explosive","Une contraction isométrique prolongée, sans mouvement","Un étirement passif maintenu, en fin d'amplitude","Une contraction concentrique lente, contre une forte résistance"],"r":0,"e":"La pliométrie active le cycle étirement/raccourcissement : pré-étirement puis contraction explosive. Il active le cycle étirement-raccourcissement.","s":8},{"q":"Quels prérequis sont exigés avant de débuter la pliométrie ?","o":["Segment sans œdème","Segment sans douleur","Amplitude articulaire normale","Force et flexibilité normales","Un âge inférieur à 40 ans"],"r":[0,1,2,3],"e":"Le segment doit être sans œdème ni douleur, avec amplitude, force et flexibilité normales.","s":8},{"q":"Quelles recommandations générales encadrent la prescription d'exercice ?","o":["Garder en vue les objectifs du patient","Évaluer puis réévaluer régulièrement","Viser le meilleur niveau de preuve","Être créatif avec mesure","Un protocole standard pour tous"],"r":[0,1,2,3],"e":"Individualisation, réévaluation, meilleur niveau de preuve et créativité mesurée. La standardisation contredit le principe d'individualisation.","s":8},{"q":"Dans la gonarthrose, quels problèmes la prescription d'exercice va-t-elle cibler ?","o":["Amplitude articulaire réduite","Flexibilité diminuée","Force musculaire diminuée","Marche et appui difficiles","Déformation osseuse fixée"],"r":[0,1,2,3],"e":"Quatre problèmes accessibles à l'exercice : ROM, flexibilité, force et difficulté de marche/appui. L'amplitude réduite correspond à la baisse du ROM.","s":8},{"q":"Dans la gonarthrose, quels piliers sont travaillés à moyen terme (6-12 semaines) ?","o":["Mobilité, force musculaire et RSM","Mobilité, flexibilité et RSM","Force musculaire, RSM et pliométrie","Pliométrie seule"],"r":0,"e":"Court terme (4-6 sem.) : mobilité, flexibilité, RSM. Moyen terme (6-12 sem.) : mobilité, force, RSM. Long terme (12-24 sem.) : force, RSM, pliométrie.","s":8}]};
